insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('grudge-shelf-inventory-sheet', 'Grudge Shelf Inventory Sheet', 'worksheet'::resource_kind, 'A shelf-by-shelf list of the grudges a client is still carrying, what each one costs, and what to do with it.', 'Use it to help a client see which old resentments still take up room and choose one to set down, keep or address.', array['Adults', 'Teens']::text[], '40 minutes', 'Draw a bookshelf with the client and let them place each grudge on a shelf by how heavy it feels. For each one, ask what it costs them now in sleep, mood or time spent rehearsing it, and what keeping it protects. Then sort: set down, keep for now, or bring to the person. Most clients are surprised how many are about people they no longer see. Keep the tone curious, not moralizing; a grudge often guards a real hurt.', '[{"id": "f0", "type": "textarea", "label": "The grudges I am still carrying, heaviest at the top:"}, {"id": "f1", "type": "textarea", "label": "What each one costs me now, in sleep, mood or time:"}, {"id": "f2", "type": "textarea", "label": "What keeping it protects me from or reminds me of:"}, {"id": "f3", "type": "textarea", "label": "One I am ready to set down, and how I would know it was down:"}, {"id": "f4", "type": "textarea", "label": "One I want to bring to the person, and the first sentence I would say:"}]'::jsonb, array['self-monitoring', 'anger', 'forgiveness']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('reasons-i-put-it-off-sorting-page', 'Reasons I Put It Off Sorting Page', 'worksheet'::resource_kind, 'A sorting page that files each delayed task under the reason it is waiting: unclear, boring, scary, too big or perfectionism.', 'Use it to match each stuck task to a fix that fits the reason, instead of one blanket push to try harder.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client list everything they are putting off, then sort each task into a column: I do not know the first step, it is dull, I am afraid of how it turns out, it is too big, or it has to be perfect. Each column has a different fix, and clients who have been telling themselves they are lazy usually find three or four different reasons on one page. Pick one task per column and name the smallest matching move.', '[{"id": "f0", "type": "textarea", "label": "Everything I am currently putting off:"}, {"id": "f1", "type": "textarea", "label": "Tasks where I do not know the first step, and what the first step might be:"}, {"id": "f2", "type": "textarea", "label": "Tasks that are simply dull, and how I could make the start bearable:"}, {"id": "f3", "type": "textarea", "label": "Tasks I am afraid of the outcome of, and what the fear is:"}, {"id": "f4", "type": "textarea", "label": "Tasks that feel too big or have to be perfect, and a good-enough version:"}, {"id": "f5", "type": "textarea", "label": "One task I will start this week, matched to its fix:"}]'::jsonb, array['task initiation', 'avoidance', 'planning']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('sleep-debt-repayment-plan-sheet', 'Sleep Debt Repayment Plan Sheet', 'worksheet'::resource_kind, 'A plan for paying back a week of short nights in small early bedtimes rather than one long weekend lie-in.', 'Use it to help a client recover from a run of short nights without wrecking their sleep rhythm.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to estimate how short each night this week ran, then plan the catch-up as several bedtimes fifteen to thirty minutes earlier and a wake time that stays fixed. Explain why the long Sunday lie-in feels good and then makes Monday worse. Watch for clients who want to fix a month of short sleep in one weekend; the sheet is a pacing tool, and it pairs well with a wind-down routine they already have.', '[{"id": "f0", "type": "textarea", "label": "Roughly how much sleep I missed each night this week:"}, {"id": "f1", "type": "textarea", "label": "My fixed wake time for the next seven days:"}, {"id": "f2", "type": "textarea", "label": "The nights I will go to bed earlier, and by how much:"}, {"id": "f3", "type": "textarea", "label": "What I will do instead of a long weekend lie-in:"}, {"id": "f4", "type": "textarea", "label": "How I will notice the debt is repaid:"}]'::jsonb, array['sleep', 'planning', 'self-care']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('news-intake-limits-planner', 'News Intake Limits Planner', 'worksheet'::resource_kind, 'A planner for when, where and how much news a client takes in, with a cutoff and a replacement for the scrolling.', 'Use it to help a client who feels saturated by news set limits they can actually keep.', array['Adults', 'Teens']::text[], '20 minutes', 'Map the client''s current intake first: which apps and channels, at what hours, and what they feel afterward. Then set a window or two for catching up, a nightly cutoff and a replacement for the habit, since the scrolling usually fills a gap rather than a need to know. Clients who feel it is irresponsible to look away often need a line about staying informed on their own terms. Review the limits after a week and adjust the window, not the principle.', '[{"id": "f0", "type": "textarea", "label": "Where and when I take in news now, and how I feel afterward:"}, {"id": "f1", "type": "textarea", "label": "The one or two windows when I will catch up this week:"}, {"id": "f2", "type": "textarea", "label": "My nightly cutoff, and what I will do with that time instead:"}, {"id": "f3", "type": "textarea", "label": "What I tell myself about looking away, and a fairer version:"}, {"id": "f4", "type": "textarea", "label": "How I will notice if the limits are working:"}]'::jsonb, array['habits', 'stress', 'boundaries']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('secondhand-stress-catch-sheet', 'Secondhand Stress Catch Sheet', 'worksheet'::resource_kind, 'A sheet for noticing when a client has picked up someone else''s stress and separating what is theirs to carry.', 'Use it to help a client who soaks up other people''s tension notice the handoff and set it down.', array['Adults', 'Teens', 'Groups']::text[], '30 minutes', 'Ask the client to recall three recent moments when they felt tense after being with someone, then work through whose stress it was, how it arrived (tone, a sigh, a text) and what they did with it. Many clients in caring roles treat absorbing stress as part of being good. The sheet separates caring about from carrying for, and ends with one small return move such as a walk, a shake-out or a sentence that hands the problem back.', '[{"id": "f0", "type": "textarea", "label": "A recent time I felt tense after being with someone:"}, {"id": "f1", "type": "textarea", "label": "Whose stress it was, and how it reached me:"}, {"id": "f2", "type": "textarea", "label": "What I did with it afterward:"}, {"id": "f3", "type": "textarea", "label": "What is mine to carry here, and what is not:"}, {"id": "f4", "type": "textarea", "label": "One move that hands the rest back or shakes it off:"}]'::jsonb, array['boundaries', 'stress', 'body awareness']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('should-statement-word-swap-sheet', 'Should Statement Word Swap Sheet', 'cbt'::resource_kind, 'A semantic-method sheet that swaps each should, must and ought for softer, truer wording and checks the feeling shift.', 'Use it to help a client loosen rigid self-rules by changing the words first and noticing what changes.', array['Adults', 'Teens']::text[], '20 minutes', 'Collect the client''s shoulds from the week, then try each in new words: it would be nice if, I would prefer, I am choosing to. Rate the feeling before and after each swap. Clients often resist, saying the should keeps them in line; test that by asking whether the should has actually produced the behavior or just the guilt. Keep one or two shoulds the client decides are real commitments, so the sheet is not read as having no standards.', '[{"id": "f0", "type": "textarea", "label": "The should, must or ought statements I caught myself using this week:"}, {"id": "f1", "type": "textarea", "label": "Each one rewritten with it would be nice if, I would prefer or I choose to:"}, {"id": "f2", "type": "textarea", "label": "How I felt reading the original, and how I feel reading the new version:"}, {"id": "f3", "type": "textarea", "label": "Which of these has the should actually helped me do:"}, {"id": "f4", "type": "textarea", "label": "One should I want to keep as a real commitment, and why:"}]'::jsonb, array['core CBT', 'self-talk', 'thinking traps']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('define-the-term-sheet', 'Define the Term Sheet', 'cbt'::resource_kind, 'A sheet that asks a client to define a harsh label they use on themselves until the definition falls apart or gets fair.', 'Use it to help a client who calls themselves a failure or a mess find out what the word would actually require.', array['Adults', 'Teens']::text[], '25 minutes', 'Take one word the client uses on themselves and ask for a definition that would apply to anyone: what exactly makes a person a failure? Then test the definition against the client and against people they respect. The definition usually either fits everyone or no one, which is the point. Stay with one word per sheet and keep the questions genuinely curious; clients can hear this as a trick if it moves too fast.', '[{"id": "f0", "type": "textarea", "label": "The label I put on myself most often:"}, {"id": "f1", "type": "textarea", "label": "My definition of that word, as it would apply to anyone:"}, {"id": "f2", "type": "textarea", "label": "People I respect who would fit this definition, and whether I call them that:"}, {"id": "f3", "type": "textarea", "label": "What my definition gets wrong, or where it falls apart:"}, {"id": "f4", "type": "textarea", "label": "A more accurate description of what actually happened:"}]'::jsonb, array['core CBT', 'self-criticism', 'thinking traps']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('acceptance-paradox-reply-sheet', 'Acceptance Paradox Reply Sheet', 'cbt'::resource_kind, 'A sheet for answering a self-critical thought by agreeing with the true part of it calmly, instead of arguing.', 'Use it to give a client a second way to answer the inner critic when disputing the thought is not working.', array['Adults', 'Teens']::text[], '25 minutes', 'Write the self-critical thought at the top, then draft two replies: one that disputes it with evidence, one that accepts whatever is true in it with equanimity, such as yes, I did make a mistake, and I am allowed to. Ask which reply the client finds more believable and more freeing. Some clients find the accepting reply lands where the arguing reply never did; others need both. Practice the accepting reply out loud in session before it goes home.', '[{"id": "f0", "type": "textarea", "label": "The self-critical thought:"}, {"id": "f1", "type": "textarea", "label": "A reply that argues with it, using facts:"}, {"id": "f2", "type": "textarea", "label": "A reply that calmly agrees with whatever part is true, without the harshness:"}, {"id": "f3", "type": "textarea", "label": "Which reply feels more believable, and which feels more freeing:"}, {"id": "f4", "type": "textarea", "label": "A situation this week where I will try the accepting reply:"}]'::jsonb, array['core CBT', 'self-criticism', 'acceptance']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('multitasking-cost-experiment-sheet', 'Multitasking Cost Experiment Sheet', 'cbt'::resource_kind, 'A behavioral experiment that compares a task done while switching with the same task done alone, timing both.', 'Use it to let a client test their belief that juggling tasks saves time, by measuring it.', array['Adults', 'Teens']::text[], 'One week', 'Pick a routine task the client usually does with messages open or a second task running. Have them predict how long each version will take and how many mistakes each will hold, then run both versions on different days and record the results. The sheet works because the client collects their own numbers rather than hearing a lecture. If the switching version wins on some measure, say so plainly and ask what it was worth to them.', '[{"id": "f0", "type": "textarea", "label": "The task I will test, and how I usually do it:"}, {"id": "f1", "type": "textarea", "label": "My prediction: time and mistakes with switching, and time and mistakes alone:"}, {"id": "f2", "type": "textarea", "label": "What actually happened on the switching day:"}, {"id": "f3", "type": "textarea", "label": "What actually happened on the single-task day:"}, {"id": "f4", "type": "textarea", "label": "What I conclude, and what I will change, if anything:"}]'::jsonb, array['behavioral experiment', 'attention', 'predictions']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('mistake-on-purpose-experiment-sheet', 'Mistake on Purpose Experiment Sheet', 'cbt'::resource_kind, 'A behavioral experiment where a client makes one small, harmless mistake on purpose and records what actually follows.', 'Use it to let a client with rigid standards test the prediction that a visible mistake brings disaster.', array['Adults', 'Teens']::text[], 'One week', 'Choose a mistake that is small, visible and harmless: a typo in a casual email, mismatched socks, a wrong word left uncorrected in conversation. Write the prediction in detail, including who will notice and what they will do, with a confidence rating. Then do it and record the results. Clients tend to choose a mistake nobody could possibly see; push for one that someone could. The debrief looks at what the evidence says about the rule, not at how uncomfortable it was.', '[{"id": "f0", "type": "textarea", "label": "The small, visible, harmless mistake I will make on purpose:"}, {"id": "f1", "type": "textarea", "label": "My prediction: who will notice, what they will do, and how sure I am, 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "What actually happened:"}, {"id": "f3", "type": "textarea", "label": "How uncomfortable it was at the time, and an hour later:"}, {"id": "f4", "type": "textarea", "label": "What the result says about my rule, in one sentence:"}]'::jsonb, array['behavioral experiment', 'perfectionism', 'predictions']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('thought-font-change-defusion-page', 'Thought Font Change Defusion Page', 'act'::resource_kind, 'A defusion page that writes a sticky thought in different fonts, sizes and colors on an imagined screen.', 'Use it to help a client see a thought as a string of words they can format rather than a fact to obey.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client write the thought plainly, then rewrite it in bubble letters, in tiny print, in a color they dislike, as a scrolling news ticker, as a text from an unknown number. Ask after each version how much pull the thought has. The exercise tends to land quickly for visual clients and to feel silly to others; if it feels silly, that is often the point, and you can name it. Pair with a values move so unhooking leads somewhere.', '[{"id": "f0", "type": "textarea", "label": "The thought that keeps hooking me, written plainly:"}, {"id": "f1", "type": "textarea", "label": "The same thought in three different fonts, sizes or colors:"}, {"id": "f2", "type": "textarea", "label": "How the thought''s pull changed with each version, from 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "What I notice about the thought now that I have formatted it:"}, {"id": "f4", "type": "textarea", "label": "What I would do next if this thought were just words on a screen:"}]'::jsonb, array['defusion', 'core ACT', 'self-talk']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('demons-on-the-boat-metaphor-page', 'Demons on the Boat Metaphor Page', 'act'::resource_kind, 'A page that casts a client''s hard thoughts and feelings as demons on a boat the client is steering toward shore.', 'Use it to help a client see that the demons can shout without taking the wheel.', array['Adults', 'Teens']::text[], '25 minutes', 'Tell the metaphor: the client is sailing toward a shore they care about, and demons below deck surface whenever the boat heads that way, threatening but never actually touching the wheel. Ask the client to name their demons, the shore they are steering for, and what the demons say when the boat turns toward it. The usual trap is that the client has been steering in circles to keep the demons quiet. Finish by naming one turn toward shore for this week.', '[{"id": "f0", "type": "textarea", "label": "The shore I am steering toward, in my own words:"}, {"id": "f1", "type": "textarea", "label": "The demons that come up when I head that way:"}, {"id": "f2", "type": "textarea", "label": "What they say or threaten:"}, {"id": "f3", "type": "textarea", "label": "What I have been doing to keep them quiet, and where that has taken the boat:"}, {"id": "f4", "type": "textarea", "label": "One turn toward shore I will make this week, demons and all:"}]'::jsonb, array['metaphor', 'willingness', 'core ACT']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('time-capsule-letter-from-a-valued-future-self', 'Time Capsule Letter From a Valued Future Self', 'act'::resource_kind, 'A letter the client writes as their future self, describing a year lived by their values, to open on a chosen date.', 'Use it to let a client hear their values spoken from the far side of acting on them.', array['Adults', 'Teens']::text[], '40 minutes', 'Set the date a year out and ask the client to write as that person: what they did that mattered, what they stopped avoiding, what they want today''s self to know. Keep the letter about actions and qualities rather than outcomes or achievements. Clients who are stuck in self-criticism tend to write a to-do list; steer them back to who they were being. Seal it, set a reminder, and plan one small move this month that the letter would mention.', '[{"id": "f0", "type": "textarea", "label": "The date I will open this letter:"}, {"id": "f1", "type": "textarea", "label": "Dear me, this year I spent my time on what matters most, which was:"}, {"id": "f2", "type": "textarea", "label": "What I stopped avoiding, and what it was like on the other side:"}, {"id": "f3", "type": "textarea", "label": "The kind of person I was with the people I love:"}, {"id": "f4", "type": "textarea", "label": "What I want you to know on the hard days:"}, {"id": "f5", "type": "textarea", "label": "One small move this month that the letter would mention:"}]'::jsonb, array['values', 'committed action', 'core ACT']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('volunteer-hour-values-experiment-page', 'Volunteer Hour Values Experiment Page', 'act'::resource_kind, 'A page for planning one hour given to something a client cares about, and noticing what it does to their week.', 'Use it to help a client test whether an hour of contribution moves them toward the life they want.', array['Adults', 'Teens', 'Groups']::text[], 'One week', 'Ask the client which value the hour would serve and help them pick something specific and reachable: a shift at a food pantry, an hour reading to a neighbor, cleaning a stretch of park. Have them rate vitality and hooked-ness before and after. The hour is an experiment, not a fix, so set it up with genuine uncertainty about what they will find. Watch for clients who turn it into another should; the hour is chosen, not owed.', '[{"id": "f0", "type": "textarea", "label": "The value this hour would serve:"}, {"id": "f1", "type": "textarea", "label": "What I will do, where, and when this week:"}, {"id": "f2", "type": "textarea", "label": "Before: how alive and how hooked I feel today, 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "After: how alive and how hooked I felt that evening, 0 to 10:"}, {"id": "f4", "type": "textarea", "label": "What I noticed during the hour, and whether I would do it again:"}]'::jsonb, array['values', 'committed action', 'connection']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('jump-height-willingness-choice-page', 'Jump Height Willingness Choice Page', 'act'::resource_kind, 'A page that frames willingness as a jump the client can take from a book, a chair or a roof, but never halfway.', 'Use it to help a client pick a willing step small enough to take fully rather than a big one taken half-heartedly.', array['Adults', 'Teens']::text[], '20 minutes', 'Explain that willingness is like jumping: you can choose how high the ledge is, but you cannot jump halfway. Then help the client set a ledge for the feeling or situation they have been avoiding, low enough that they will fully commit. Many clients pick a roof, step off with one foot and call willingness a failure. Rate the actual jump afterward on whether it was complete, not on how it felt.', '[{"id": "f0", "type": "textarea", "label": "The feeling or situation I have been edging around:"}, {"id": "f1", "type": "textarea", "label": "The roof version of this jump, which I am not taking yet:"}, {"id": "f2", "type": "textarea", "label": "The book or chair version I can take fully this week:"}, {"id": "f3", "type": "textarea", "label": "What I will do with my body and attention during the jump:"}, {"id": "f4", "type": "textarea", "label": "Afterward: did I jump all the way, and what happened:"}]'::jsonb, array['willingness', 'core ACT', 'exposure']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('model-of-emotions-chain-sheet', 'Model of Emotions Chain Sheet', 'dbt'::resource_kind, 'A sheet that walks one emotion from prompting event through interpretation, body change, urge, action and aftereffects.', 'Use it to show a client where in the chain of an emotion they have room to do something different.', array['Adults', 'Teens']::text[], '30 minutes', 'Take one emotional moment from the week and fill the chain together: the prompting event, the vulnerability factors, the interpretation, what the body did, the urge, what the client actually did, and the aftereffects. Then mark each link where a skill could enter. Clients often skip from event to action; slow the middle down. The sheet pairs with check the facts at the interpretation link and opposite action at the urge link.', '[{"id": "f0", "type": "textarea", "label": "The prompting event, in a sentence:"}, {"id": "f1", "type": "textarea", "label": "What made me vulnerable that day (sleep, hunger, stress, earlier events):"}, {"id": "f2", "type": "textarea", "label": "How I read the event, in the moment:"}, {"id": "f3", "type": "textarea", "label": "What my body did, and what I felt the urge to do:"}, {"id": "f4", "type": "textarea", "label": "What I actually did, and what happened afterward:"}, {"id": "f5", "type": "textarea", "label": "The link in this chain where a skill would fit best:"}]'::jsonb, array['core DBT', 'emotion regulation', 'formulation']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('emotion-myths-check-sheet', 'Emotion Myths Check Sheet', 'dbt'::resource_kind, 'A sheet listing common beliefs about emotions for the client to rate and answer with a more workable statement.', 'Use it to surface the rules a client holds about feelings that keep them from using regulation skills.', array['Adults', 'Teens', 'Groups']::text[], '30 minutes', 'Read through myths such as there is a right way to feel, negative feelings are bad, letting others see my feelings is weakness, and painful emotions are unimportant. Have the client rate how much they believe each, then write a challenge in their own words. Do not argue clients out of a myth; ask where they learned it and what it has cost. The sheet works well in groups, where hearing another member''s challenge often lands better than yours.', '[{"id": "f0", "type": "textarea", "label": "The emotion beliefs I rate most strongly, and where I think I learned them:"}, {"id": "f1", "type": "textarea", "label": "What each belief has cost me:"}, {"id": "f2", "type": "textarea", "label": "A challenge to the first belief, in my own words:"}, {"id": "f3", "type": "textarea", "label": "A challenge to the second belief, in my own words:"}, {"id": "f4", "type": "textarea", "label": "One belief I am not ready to let go of, and why:"}]'::jsonb, array['core DBT', 'emotion regulation', 'psychoeducation']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('observing-my-limits-sheet', 'Observing My Limits Sheet', 'dbt'::resource_kind, 'A sheet for noticing where a client''s limits actually are with a particular person and saying so before they are crossed.', 'Use it to help a client who only notices a limit after it has been run over state it early and plainly.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick one relationship where the client ends up resentful. Have them notice the early body signals that a limit is close, name the limit in a sentence, and plan when and how to say it before the breaking point. Limits here are personal and can change, which is the piece most clients have not been told. Rehearse the sentence in session; the usual slip is waiting until the limit is well past and then delivering it as an accusation.', '[{"id": "f0", "type": "textarea", "label": "The person and situation where I end up resentful:"}, {"id": "f1", "type": "textarea", "label": "The early signals in my body that a limit is near:"}, {"id": "f2", "type": "textarea", "label": "My limit here, in one plain sentence:"}, {"id": "f3", "type": "textarea", "label": "When and how I will say it, before it is crossed:"}, {"id": "f4", "type": "textarea", "label": "What I will do if it is crossed anyway:"}]'::jsonb, array['interpersonal effectiveness', 'boundaries', 'core DBT']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('teflon-mind-practice-card', 'Teflon Mind Practice Card', 'dbt'::resource_kind, 'A pocket card for letting thoughts, images and urges slide off the mind without sticking, one minute at a time.', 'Use it to give a client a short mindfulness practice for busy minds that will not quiet down.', array['Adults', 'Teens']::text[], 'Five minutes daily for two weeks', 'Teach the image: the mind as a nonstick pan, where thoughts land and slide off without being scrubbed at. Set a one-minute timer and have the client notice each thought, let it slide, and return to the breath, without judging the slide or the stick. Build to five minutes. Clients often report failing because thoughts kept coming; reframe the practice as noticing the sliding, not stopping the landing. Log what stuck most, since that is useful material.', '[{"id": "f0", "type": "textarea", "label": "Today''s practice length, and when I did it:"}, {"id": "f1", "type": "textarea", "label": "The thoughts, images or urges that landed, in a few words:"}, {"id": "f2", "type": "textarea", "label": "Which slid off easily and which stuck:"}, {"id": "f3", "type": "textarea", "label": "What I did when one stuck:"}, {"id": "f4", "type": "textarea", "label": "How my mind felt afterward, compared with before:"}]'::jsonb, array['mindfulness', 'core DBT', 'defusion']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('wants-versus-shoulds-balance-sheet', 'Wants Versus Shoulds Balance Sheet', 'dbt'::resource_kind, 'A two-column sheet weighing the things a client does because they want to against the things they do because they should.', 'Use it to help a client whose week is all obligation or all impulse find a workable balance.', array['Adults', 'Teens']::text[], '25 minutes', 'List the past week''s activities in two columns: wanted to and had to. Count them, then ask what the ratio does to mood. Clients heavy on shoulds tend to burn out and resent; clients heavy on wants tend to feel chaotic and guilty. Neither column is the enemy. Plan one addition to the thin column for next week and notice what gets in the way. Revisit the sheet monthly as a quick read on the client''s life.', '[{"id": "f0", "type": "textarea", "label": "Things I did this week because I wanted to:"}, {"id": "f1", "type": "textarea", "label": "Things I did this week because I had to:"}, {"id": "f2", "type": "textarea", "label": "What the balance does to my mood and energy:"}, {"id": "f3", "type": "textarea", "label": "One thing I will add to the thinner column next week:"}, {"id": "f4", "type": "textarea", "label": "What might get in the way, and how I will handle it:"}]'::jsonb, array['core DBT', 'emotion regulation', 'self-care']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('twenty-second-hug-daily-ritual-card', 'Twenty-Second Hug Daily Ritual Card', 'couples'::resource_kind, 'A card that sets up one unhurried twenty-second hug a day, with each partner''s part and a note on what came up.', 'Use it to give a couple one small daily moment of physical connection that is not a prelude to anything else.', array['Couples']::text[], 'One minute daily for two weeks', 'Ask the couple to pick a time, agree that the hug is complete in itself, and let one partner count silently to twenty. Both partners notice what happens in their bodies and what the mind says. Partners who are out of the habit of touch often feel awkward for the first few days; name that as expected. Check in after a week on whether either partner felt pressured, and adjust the time rather than dropping the ritual.', '[{"id": "f0", "type": "textarea", "label": "The time of day we will take our twenty-second hug:"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I noticed in my body and mind during the hug this week:"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I noticed in my body and mind during the hug this week:"}, {"id": "f3", "type": "textarea", "label": "A day it felt awkward or got skipped, and what was going on:"}, {"id": "f4", "type": "textarea", "label": "What we want to keep or change about it:"}]'::jsonb, array['couples', 'connection', 'rituals']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('nonverbal-cue-decoding-sheet-for-partners', 'Nonverbal Cue Decoding Sheet for Partners', 'couples'::resource_kind, 'A sheet where each partner describes the sighs, looks and silences they read in the other, and the other says what they meant.', 'Use it to clear up the misreads of tone and face that start arguments before a word is spoken.', array['Couples']::text[], 'Full session', 'Each partner lists three nonverbal cues from the other that they react to, what they take them to mean, and what they do in response. The other partner then says what the cue usually means on their end. The gap is often wide: a sigh read as contempt was about the dishwasher. Keep the tone of discovery, and stop either partner from using the sheet to prove the other is always misreading. Agree on one cue each to check out loud next time.', '[{"id": "f0", "type": "textarea", "label": "Partner A: three looks, sounds or silences from my partner that I react to, and what I take them to mean:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what each of those cues usually means on my side:"}, {"id": "f2", "type": "textarea", "label": "Partner B: three cues from my partner that I react to, and what I take them to mean:"}, {"id": "f3", "type": "textarea", "label": "Partner A: what each of those cues usually means on my side:"}, {"id": "f4", "type": "textarea", "label": "One cue each of us will check out loud instead of reading, and the words we will use:"}]'::jsonb, array['couples', 'communication', 'conflict']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('gift-giving-expectations-talk-sheet', 'Gift Giving Expectations Talk Sheet', 'couples'::resource_kind, 'A sheet that lets partners say what gifts mean to each of them before the next birthday or holiday disappoints someone.', 'Use it to help a couple stop a recurring hurt about presents by naming what each one is really asking for.', array['Couples']::text[], '45 minutes', 'Have each partner describe how gifts worked in the home they grew up in, a gift that meant a lot, and one that stung. Then each says what a gift tells them: effort, attention, being known, or simply that the day was remembered. Partners usually discover they are grading on different scales. Agree on a budget range, whether lists are welcome, and one thing each will do differently for the next occasion.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how gifts worked where I grew up, and a gift that meant a lot or stung:"}, {"id": "f1", "type": "textarea", "label": "Partner B: how gifts worked where I grew up, and a gift that meant a lot or stung:"}, {"id": "f2", "type": "textarea", "label": "What a gift from my partner tells me, in each of our words:"}, {"id": "f3", "type": "textarea", "label": "What we agree about budget, lists and surprises:"}, {"id": "f4", "type": "textarea", "label": "One thing each of us will do differently for the next occasion:"}]'::jsonb, array['couples', 'appreciation', 'communication']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('sleep-schedule-mismatch-talk-sheet', 'Sleep Schedule Mismatch Talk Sheet', 'couples'::resource_kind, 'A sheet for a night owl and an early bird to work out bedtimes, wake times and the connection that gets lost between them.', 'Use it to help partners with different sleep rhythms protect both their rest and their time together.', array['Couples']::text[], '45 minutes', 'Map each partner''s natural sleep and wake times and what the gap costs: one goes to bed alone, one is woken early, the evening conversation never happens. Then look for a shared window at either end of the day and agree on noise, light and phone rules for the one still awake. Resist solving it by making one partner adopt the other''s rhythm; the sheet is about meeting in the overlap. Review after two weeks of trying it.', '[{"id": "f0", "type": "textarea", "label": "Partner A: when I naturally fall asleep and wake, and what the mismatch costs me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: when I naturally fall asleep and wake, and what the mismatch costs me:"}, {"id": "f2", "type": "textarea", "label": "The window in the day we can protect for being together:"}, {"id": "f3", "type": "textarea", "label": "Our agreements about light, noise and screens when one of us is asleep:"}, {"id": "f4", "type": "textarea", "label": "What we will try for two weeks, and when we will talk about how it went:"}]'::jsonb, array['couples', 'sleep', 'routines']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('hinting-versus-asking-practice-sheet-for-partners', 'Hinting Versus Asking Practice Sheet for Partners', 'couples'::resource_kind, 'A sheet that turns each partner''s recent hints into direct requests and lets the other partner say how each landed.', 'Use it to help a couple replace hints that go unnoticed with asks that can be answered.', array['Couples']::text[], '45 minutes', 'Each partner writes three things they hinted at this month and what they hoped would happen. The other partner says whether they caught the hint. Then rewrite each hint as a direct, specific request and practice saying it. The partner who hints often fears that asking is demanding or that a gift asked for does not count; the partner who misses hints often feels tested. Name both fears before the rewrites so the exercise does not become a scoreboard.', '[{"id": "f0", "type": "textarea", "label": "Partner A: three things I hinted at recently, and what I hoped would happen:"}, {"id": "f1", "type": "textarea", "label": "Partner B: which of those hints I caught, and what I thought they meant:"}, {"id": "f2", "type": "textarea", "label": "Partner B: three things I hinted at recently, and what I hoped would happen:"}, {"id": "f3", "type": "textarea", "label": "Partner A: which of those hints I caught, and what I thought they meant:"}, {"id": "f4", "type": "textarea", "label": "Each hint rewritten as a direct request, and how it felt to say and to hear:"}]'::jsonb, array['couples', 'communication', 'assertiveness']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('feelings-paint-mixing-chart', 'Feelings Paint Mixing Chart', 'kids'::resource_kind, 'A painting activity where a child mixes two feeling colors to make the color of a mixed-up feeling.', 'Use it to help a child see that two feelings can be there at once, and to name the mix.', array['Children']::text[], '30 minutes', 'Have the child assign a color to a few feelings, then pick two that showed up together recently, such as excited and scared before a sleepover, and mix the paints to make that feeling''s color. Name the new color together. The parent paints alongside, mixing a feeling pair of their own, and says it out loud so the child hears a grown-up have two feelings at once. Keep the chart; it becomes a vocabulary the family can point to.', '[{"id": "f0", "type": "textarea", "label": "My feeling colors: happy is, sad is, mad is, scared is, excited is:"}, {"id": "f1", "type": "textarea", "label": "Two feelings I had at the same time, and when:"}, {"id": "f2", "type": "textarea", "label": "The color they made when I mixed them, and its name:"}, {"id": "f3", "type": "textarea", "label": "A mixed feeling my grown-up painted:"}, {"id": "f4", "type": "textarea", "label": "Where we will keep the chart so we can point to it:"}]'::jsonb, array['children', 'emotion identification', 'art']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('marble-jar-bravery-counter-craft', 'Marble Jar Bravery Counter Craft', 'kids'::resource_kind, 'A decorated jar that gets one marble each time a child does a brave or kind thing, with a plan for when it is full.', 'Use it to help a parent notice and mark small brave moments instead of only the big ones.', array['Children']::text[], '30 minutes to set up, then daily', 'Decorate the jar together and agree on what earns a marble: trying something new, telling the truth when it was hard, helping without being asked. The parent drops the marble in while naming the exact behavior, and the child can add one for themselves too. Agree in advance on what happens when the jar is full, ideally a shared activity rather than a purchase. Watch for marbles being taken out as punishment; the jar only goes up.', '[{"id": "f0", "type": "textarea", "label": "What I decorated my jar with:"}, {"id": "f1", "type": "textarea", "label": "The brave and kind things that earn a marble in our house:"}, {"id": "f2", "type": "textarea", "label": "What we will do together when the jar is full:"}, {"id": "f3", "type": "textarea", "label": "A marble I earned this week and what it was for:"}, {"id": "f4", "type": "textarea", "label": "A marble my grown-up earned, and what it was for:"}]'::jsonb, array['children', 'strengths', 'craft']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('hopes-kite-decorating-craft', 'Hopes Kite Decorating Craft', 'kids'::resource_kind, 'A paper kite a child decorates with hopes on the sail and worries on the tail, then flies or hangs up.', 'Use it to help a child put hopes and worries side by side and feel the hopes lift the worries along.', array['Children']::text[], '40 minutes', 'Build a simple paper kite with the child. On the sail they draw or write things they are hoping for; each bow on the tail holds one worry. Fly it outside if the weather allows, or hang it in a window. The parent helps with the cutting, adds one hope and one worry of their own to the tail, and talks about how the kite needs both to fly straight. Avoid turning the worries into problems to solve on the spot; the craft is about carrying them.', '[{"id": "f0", "type": "textarea", "label": "The hopes I drew on my kite''s sail:"}, {"id": "f1", "type": "textarea", "label": "The worries I tied to the tail:"}, {"id": "f2", "type": "textarea", "label": "A hope and a worry my grown-up added:"}, {"id": "f3", "type": "textarea", "label": "Where we flew or hung the kite:"}, {"id": "f4", "type": "textarea", "label": "What I noticed when the kite was up:"}]'::jsonb, array['children', 'craft', 'worry']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('hot-cocoa-breathing-play', 'Hot Cocoa Breathing Play', 'kids'::resource_kind, 'A pretend-play breathing game where a child smells an imaginary mug of cocoa and blows slowly to cool it.', 'Use it to teach a child slow in-and-out breathing with a picture they will remember when upset.', array['Children']::text[], 'Ten minutes, then as needed', 'Cup your hands as a mug and model it: breathe in through the nose to smell the cocoa, then blow out slowly through the mouth so you cool it without spilling. Do five rounds together and let the child add toppings. The parent practices it at calm times first so the child knows the game before the hard moment, then offers a cocoa breath when things heat up, doing it alongside rather than instructing. Three rounds usually shift a small body.', '[{"id": "f0", "type": "textarea", "label": "What is in my pretend mug today:"}, {"id": "f1", "type": "textarea", "label": "How many cocoa breaths we did together:"}, {"id": "f2", "type": "textarea", "label": "When my grown-up and I practiced at a calm time:"}, {"id": "f3", "type": "textarea", "label": "A hard moment when we tried a cocoa breath, and what happened:"}, {"id": "f4", "type": "textarea", "label": "What I like to add on top:"}]'::jsonb, array['children', 'breathing', 'play']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('calm-place-shoebox-diorama-craft', 'Calm Place Shoebox Diorama Craft', 'kids'::resource_kind, 'A shoebox scene a child builds of a real or imagined calm place, to look into when things feel too big.', 'Use it to give a child a three-dimensional calm place they made with their own hands.', array['Children']::text[], 'One hour', 'Gather a shoebox, paper, cotton, small toys and glue, and ask the child to build the calmest place they can imagine inside it. Ask what they would hear, smell and touch there as they build. The parent handles the hot glue or scissors, adds one small object the child chooses, and later invites the child to look into the box and breathe when they are winding up. Keep it somewhere the child can reach without asking.', '[{"id": "f0", "type": "textarea", "label": "My calm place is:"}, {"id": "f1", "type": "textarea", "label": "What I can hear, smell and touch there:"}, {"id": "f2", "type": "textarea", "label": "The things I put inside my box:"}, {"id": "f3", "type": "textarea", "label": "The object my grown-up added:"}, {"id": "f4", "type": "textarea", "label": "Where my box lives so I can look into it:"}]'::jsonb, array['children', 'self-soothing', 'craft']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('beach-ball-question-toss-game', 'Beach Ball Question Toss Game', 'game'::resource_kind, 'A group game with a beach ball covered in questions; whoever catches it answers the one under their right thumb.', 'Use it to warm up a group and get quieter members talking about feelings and coping with no one on the spot for long.', array['Groups', 'Teens', 'Children']::text[], '20 minutes', 'Write a question in each colored panel of an inflatable ball, ranging from easy (a food you love) to feelings and coping (something that calmed you this week). Rules: toss gently, the catcher answers the question under their right thumb in one or two sentences, passing is allowed once, then toss to someone who has not had it. Play three rounds. Debrief by asking which question was hardest to answer and what made the easy ones easy.', '[{"id": "f0", "type": "textarea", "label": "The question I got, and what I answered:"}, {"id": "f1", "type": "textarea", "label": "A question someone else got that I would have liked:"}, {"id": "f2", "type": "textarea", "label": "The hardest question on the ball, and why:"}, {"id": "f3", "type": "textarea", "label": "Something I learned about another person in the group:"}, {"id": "f4", "type": "textarea", "label": "One question I would add to the ball:"}]'::jsonb, array['game', 'group', 'connection']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('human-knot-teamwork-game', 'Human Knot Teamwork Game', 'game'::resource_kind, 'A standing group puzzle where everyone grabs hands across a circle and untangles without letting go.', 'Use it to get a group working together, talking under mild frustration and debriefing how they handled it.', array['Groups', 'Teens']::text[], '20 minutes', 'Stand in a circle, each person reaches across and takes two different people''s hands, then the group untangles into a circle without letting go. Rules: no letting go, hands may pivot, anyone can call a thirty-second pause. Set a time limit and let it fail if it fails. Debrief on who led, who went quiet, what the frustration felt like in the body and what helped; the game is a safe stand-in for any group task that gets stuck.', '[{"id": "f0", "type": "textarea", "label": "What I did when the knot got frustrating:"}, {"id": "f1", "type": "textarea", "label": "Who led, and how the group decided to listen:"}, {"id": "f2", "type": "textarea", "label": "What I noticed in my body during the hard part:"}, {"id": "f3", "type": "textarea", "label": "What helped us untangle, or what got in the way:"}, {"id": "f4", "type": "textarea", "label": "A real situation this reminds me of:"}]'::jsonb, array['game', 'group', 'problem solving']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('simon-says-body-signals-game', 'Simon Says Body Signals Game', 'game'::resource_kind, 'A Simon Says round where the commands are early body signals of feelings, played fast and then debriefed.', 'Use it to help a group learn the body signals of anger, worry and sadness by acting them out and catching them.', array['Children', 'Teens', 'Groups']::text[], '15 minutes', 'The leader calls commands such as Simon says clench your jaw, Simon says breathe fast and shallow, Simon says slump your shoulders, mixed with ordinary ones. Players who move without the Simon says sit out one round. After a few rounds, swap leaders. Debrief by asking which body signals felt familiar, which feelings they usually come with, and what the group could do the moment they notice one in real life.', '[{"id": "f0", "type": "textarea", "label": "A body signal command that felt familiar to me:"}, {"id": "f1", "type": "textarea", "label": "The feeling that usually comes with that signal:"}, {"id": "f2", "type": "textarea", "label": "A signal I had not thought of as a feeling before:"}, {"id": "f3", "type": "textarea", "label": "What I could do the moment I notice that signal for real:"}, {"id": "f4", "type": "textarea", "label": "A command I would add if I were Simon:"}]'::jsonb, array['game', 'body awareness', 'emotion identification']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('mirror-me-pairs-game', 'Mirror Me Pairs Game', 'game'::resource_kind, 'A pairs game where one partner moves slowly and the other mirrors them, then they switch and debrief.', 'Use it to build attention to another person and give a group an easy way to practice following and leading.', array['Groups', 'Teens', 'Children']::text[], '15 minutes', 'Pairs face each other; one leads with slow movements and facial expressions, the other mirrors as exactly as they can for two minutes, then they switch. Round three: no leader, both try to move together. Rules: slow enough to follow, no talking, no trying to trick the mirror. Debrief on which role was harder, what it took to stay with the other person, and when in real life they tend to lead, follow or lose the other person entirely.', '[{"id": "f0", "type": "textarea", "label": "Which role was harder for me, leading or mirroring, and why:"}, {"id": "f1", "type": "textarea", "label": "What it took to stay with my partner:"}, {"id": "f2", "type": "textarea", "label": "What happened in the round with no leader:"}, {"id": "f3", "type": "textarea", "label": "When in real life I tend to lead, follow or lose the other person:"}, {"id": "f4", "type": "textarea", "label": "One thing I noticed about my partner that I had not before:"}]'::jsonb, array['game', 'group', 'social skills']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('describe-it-without-saying-it-game', 'Describe It Without Saying It Game', 'game'::resource_kind, 'A card game where players describe a feeling or coping skill without using the obvious words, and teammates guess.', 'Use it to stretch a group''s feelings vocabulary and get them describing experiences from the inside.', array['Teens', 'Groups', 'Children']::text[], '25 minutes', 'Make cards with a feeling or skill on top and three forbidden words underneath, such as anger with mad, angry and furious. Players take turns describing their card in sixty seconds while their team guesses; saying a forbidden word loses the card. Play to ten points. Debrief on which cards were hardest to describe, what words the group reached for instead, and how it felt to describe a feeling by what it does in the body and the mind rather than by its name.', '[{"id": "f0", "type": "textarea", "label": "The card I found hardest to describe, and the words I used instead:"}, {"id": "f1", "type": "textarea", "label": "A description someone gave that I thought was perfect:"}, {"id": "f2", "type": "textarea", "label": "A feeling I realized I only have one word for:"}, {"id": "f3", "type": "textarea", "label": "What it was like to describe a feeling by what it does instead of its name:"}, {"id": "f4", "type": "textarea", "label": "A card I would add to the deck:"}]'::jsonb, array['game', 'emotion identification', 'group']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('hard-nights-bedroom-setup-checklist', 'Hard Nights Bedroom Setup Checklist', 'worksheet'::resource_kind, 'A checklist for arranging the bedroom so that waking in the night lands the client somewhere that feels safe and present.', 'Use it to help a client make the room they wake up in do some of the grounding for them.', array['Adults', 'Teens']::text[], '30 minutes', 'Walk through the room item by item: a light within reach, a clock that shows the date, a grounding object on the nightstand, the door the way the client wants it, a note with two steadying sentences. Ask what the client reaches for first on a bad night and put that closer. The checklist stays on the present-day room and never on the content of dreams; if the client starts to describe what wakes them, slow down and return to the setup. Revisit after a week.', '[{"id": "f0", "type": "textarea", "label": "What I reach for first when I wake in the night:"}, {"id": "f1", "type": "textarea", "label": "The light, clock and grounding object I will keep within arm''s reach:"}, {"id": "f2", "type": "textarea", "label": "How I want the door, the window and the sounds in the room:"}, {"id": "f3", "type": "textarea", "label": "Two sentences I will keep on my nightstand to read:"}, {"id": "f4", "type": "textarea", "label": "Who I can text or call if the night is very hard, including 988 by call or text:"}, {"id": "f5", "type": "textarea", "label": "One change I will make to the room tonight:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'sleep']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('flashback-halting-statements-card', 'Flashback Halting Statements Card', 'dbt'::resource_kind, 'A pocket card of present-tense statements a client reads aloud when a memory starts to feel like now.', 'Use it to give a client a scripted way to name the here and now when the past intrudes.', array['Adults', 'Teens']::text[], '15 minutes to build, then as needed', 'Write the card together in session: my name is, I am years old, today''s date is, I am in, the thing I am remembering happened then and is not happening now, I am safe enough right now, and I can look around and name three things I see. Have the client read it aloud once in session so the voice is familiar. Keep the card to facts of the present; it never names what the memory is. Pair it with a sensory anchor they already use.', '[{"id": "f0", "type": "textarea", "label": "My name, my age today, and the date:"}, {"id": "f1", "type": "textarea", "label": "Where I am right now, and who is nearby or reachable:"}, {"id": "f2", "type": "textarea", "label": "A sentence that says the memory is from then, not now:"}, {"id": "f3", "type": "textarea", "label": "Three things I can see and two I can touch from where I am:"}, {"id": "f4", "type": "textarea", "label": "Who I will tell that I used the card, so we can review it:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'distress tolerance']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('dreading-bedtime-thought-check-sheet', 'Dreading Bedtime Thought Check Sheet', 'cbt'::resource_kind, 'A sheet for the thoughts that arrive at bedtime about what the night will bring, with a fairer prediction beside each.', 'Use it to help a client who delays sleep out of dread look at the bedtime predictions and test them gently.', array['Adults', 'Teens']::text[], '20 minutes', 'Collect the thoughts that come as the evening ends, such as tonight will be terrible or I will not cope, and rate how sure the client is. Then build a fairer prediction from the past two weeks of nights, including the ones that were ordinary. Do not ask the client to describe dreams or what they fear remembering; the sheet is about the forecast, not the content. Pair it with the bedroom setup and a plan for what to do if the night is hard.', '[{"id": "f0", "type": "textarea", "label": "The thoughts I have as bedtime gets closer:"}, {"id": "f1", "type": "textarea", "label": "How sure I am of each, 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "Of the last fourteen nights, how many were ordinary, hard, or very hard:"}, {"id": "f3", "type": "textarea", "label": "A fairer prediction for tonight, based on that count:"}, {"id": "f4", "type": "textarea", "label": "What I will do if the night is hard, step by step:"}]'::jsonb, array['PTSD and trauma', 'sleep', 'predictions']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('count-backward-relay-game', 'Count Backward Relay Game', 'game'::resource_kind, 'A grounding relay where teams count backward by threes or sevens, passing a token, with a debrief on what it did to the body.', 'Use it to give a group a playful rehearsal of a thinking task that pulls attention back to the present.', array['Groups', 'Teens', 'Adults']::text[], '15 minutes', 'Form two lines. The first player says 100, passes a token, the next says 97, and so on; a wrong number sends the token back one place. First team to reach zero wins. Round two uses sevens from 150. Debrief by asking what the counting did to racing thoughts and to the body, and whether anyone could feel the pull back to the room. Offer the counting as one tool among several for moments when the mind drifts somewhere hard, and ask who would use it.', '[{"id": "f0", "type": "textarea", "label": "What happened to my thoughts while I was counting:"}, {"id": "f1", "type": "textarea", "label": "What I noticed in my body by the end of the round:"}, {"id": "f2", "type": "textarea", "label": "Whether I felt pulled back into the room, and when:"}, {"id": "f3", "type": "textarea", "label": "A real moment when counting backward might help me:"}, {"id": "f4", "type": "textarea", "label": "Another counting or naming task I would add to the relay:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'game']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('code-word-pause-agreement-for-partners', 'Code Word Pause Agreement for Partners', 'couples'::resource_kind, 'An agreement that gives a couple one private word that means I need a pause, no questions, with what each partner does next.', 'Use it to let a partner step out of an overwhelming moment without explaining it in the moment.', array['Couples']::text[], '45 minutes', 'Help the couple pick a neutral word, agree what it means (I am overwhelmed and need a few minutes, this is not about you) and what each partner does when it is said: one steps away to a planned spot and uses a grounding skill, the other stops talking, does something settling and waits for the return signal. Set a return time. Neither partner asks for details of what came up; the debrief, if any, is for later or for session. Rehearse it once in session.', '[{"id": "f0", "type": "textarea", "label": "Our code word, and exactly what it means:"}, {"id": "f1", "type": "textarea", "label": "Partner A: where I will go and what I will do when I say it or hear it:"}, {"id": "f2", "type": "textarea", "label": "Partner B: where I will go and what I will do when I say it or hear it:"}, {"id": "f3", "type": "textarea", "label": "How long the pause lasts, and the signal that it is over:"}, {"id": "f4", "type": "textarea", "label": "What we will not ask each other in the moment, and when we will talk about it instead:"}]'::jsonb, array['PTSD and trauma', 'couples', 'safety']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('search-engine-reassurance-log', 'Search Engine Reassurance Log', 'worksheet'::resource_kind, 'A log of each time a client looks something up to feel better, what they typed, and how long the relief lasted.', 'Use it to help a client see the pattern in online reassurance seeking and set a first limit.', array['Adults', 'Teens']::text[], 'One week', 'Ask the client to note each search done to calm a worry, including health, relationship and safety searches, with the question typed, the time, and how long the relief lasted before the next search. Most clients find the relief shrinks across the week while the searching grows. Use the log to set one limit, such as a single search per worry or a fifteen-minute delay, and track what the worry does when the search is skipped.', '[{"id": "f0", "type": "textarea", "label": "What I searched, when, and the worry behind it:"}, {"id": "f1", "type": "textarea", "label": "How anxious I felt before, and right after, 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "How long the relief lasted before I wanted to look again:"}, {"id": "f3", "type": "textarea", "label": "What I noticed about the pattern across the week:"}, {"id": "f4", "type": "textarea", "label": "The one limit I will try next week, and what the worry does when I keep it:"}]'::jsonb, array['anxiety', 'self-monitoring', 'uncertainty']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('attention-training-sound-shift-practice-log', 'Attention Training Sound Shift Practice Log', 'cbt'::resource_kind, 'A log for a daily practice of moving attention between several sounds on cue, building a flexible focus.', 'Use it to help a client whose attention is locked on worry or on their body practice steering it on purpose.', array['Adults', 'Teens']::text[], 'Ten minutes daily for two weeks', 'Set up three to five sounds in the room or at a window: a clock, traffic, a fan, birds. For a few minutes the client holds attention on one sound at a time as you call them, then shifts faster between them, then tries to hold all of them at once. Make clear the practice is not for relaxing and not for pushing worry away; it is reps for the attention muscle. Clients who try to use it as distraction in a panic tend to feel it failed, so keep practice to calm times at first.', '[{"id": "f0", "type": "textarea", "label": "The sounds I used today and where I practiced:"}, {"id": "f1", "type": "textarea", "label": "How hard it was to hold one sound, 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "How hard it was to shift quickly between them:"}, {"id": "f3", "type": "textarea", "label": "Where my attention went when it wandered:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about my attention later in the day:"}]'::jsonb, array['anxiety', 'attention', 'worry']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('pushy-friend-texts-defusion-page', 'Pushy Friend Texts Defusion Page', 'act'::resource_kind, 'A page that reframes anxious thoughts as texts from a pushy friend the client can read, acknowledge and not answer.', 'Use it to help a client let anxious thoughts arrive without treating each one as a question that needs a reply.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client write the week''s anxious thoughts as text messages from a friend who means well and will not stop: Are you sure you locked it? What if they are annoyed with you? Then practice reading each one, replying thanks, got it, and putting the phone down. The point is not to mute the friend but to stop answering every text. Clients who feel they must resolve each worry will find this hard at first; start with the smaller texts.', '[{"id": "f0", "type": "textarea", "label": "The anxious texts my mind sent this week, written as messages:"}, {"id": "f1", "type": "textarea", "label": "What I usually do when one arrives:"}, {"id": "f2", "type": "textarea", "label": "My short reply that acknowledges without answering:"}, {"id": "f3", "type": "textarea", "label": "What happened when I did not answer a text today:"}, {"id": "f4", "type": "textarea", "label": "What I did with the time I did not spend replying:"}]'::jsonb, array['anxiety', 'defusion', 'worry']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-worrying-grid', 'Pros and Cons of Worrying Grid', 'dbt'::resource_kind, 'A four-box grid weighing what worrying gives and costs against what not worrying would give and cost.', 'Use it to help a client who believes worry keeps them safe look at both sides before changing it.', array['Adults', 'Teens']::text[], '30 minutes', 'Fill all four boxes with the client: pros of worrying, cons of worrying, pros of not worrying, cons of not worrying. Take the pros of worrying seriously, since clients usually hold a belief that it prepares them or shows they care. Then ask which boxes hold facts and which hold feelings. The grid often ends with the client keeping planning and dropping rehearsing, which is a fair place to land. Return to it when the urge to worry spikes.', '[{"id": "f0", "type": "textarea", "label": "What worrying gives me:"}, {"id": "f1", "type": "textarea", "label": "What worrying costs me:"}, {"id": "f2", "type": "textarea", "label": "What I imagine not worrying would give me:"}, {"id": "f3", "type": "textarea", "label": "What I fear not worrying would cost me:"}, {"id": "f4", "type": "textarea", "label": "Looking at all four boxes, what I want to keep and what I want to drop:"}]'::jsonb, array['anxiety', 'worry', 'distress tolerance']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('brave-beads-bracelet-craft', 'Brave Beads Bracelet Craft', 'kids'::resource_kind, 'A bracelet a child strings one bead at a time, each bead for a brave moment they chose to have.', 'Use it to help a worried child and their parent mark brave moments on something the child can wear.', array['Children']::text[], '30 minutes to start, then ongoing', 'Start with the cord and three beads for brave things the child has already done. Then the parent and child agree on what earns a bead: trying a new food, saying hello first, sleeping with the light lower. The parent threads the bead with the child while naming the exact brave act, and never removes a bead. When the worry shows up, the child can count the beads. Keep it about chosen brave moments, not about being unafraid.', '[{"id": "f0", "type": "textarea", "label": "Three brave things I have already done, one bead each:"}, {"id": "f1", "type": "textarea", "label": "The brave things that will earn a new bead:"}, {"id": "f2", "type": "textarea", "label": "A brave moment I had this week, and its bead''s color:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up said when they threaded it:"}, {"id": "f4", "type": "textarea", "label": "How counting my beads felt when a worry came:"}]'::jsonb, array['anxiety', 'children', 'craft']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('reach-out-text-tally-sheet', 'Reach Out Text Tally Sheet', 'worksheet'::resource_kind, 'A tally of one small contact a day, a text or a wave, with what the client expected and what happened.', 'Use it to help a client who has gone quiet rebuild contact in moves small enough to actually send.', array['Adults', 'Teens']::text[], 'One week', 'Agree on the smallest contact the client can manage: a text, a reply left unsent, a thumbs-up, a hello to a neighbor. One a day, tallied. Have them write what they expected before each one, since clients with low mood usually predict being a burden, and then record what actually came back, including silence. Review the predictions against the outcomes at the end of the week. Do not escalate to calls or visits until the texts feel ordinary.', '[{"id": "f0", "type": "textarea", "label": "The smallest contact I can manage right now:"}, {"id": "f1", "type": "textarea", "label": "Each day: who I reached, and what I expected would happen:"}, {"id": "f2", "type": "textarea", "label": "What actually came back, including nothing:"}, {"id": "f3", "type": "textarea", "label": "How I felt in the hour after sending, compared with the hour before:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about my predictions by the end of the week:"}]'::jsonb, array['depression', 'behavioral activation', 'connection']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('nothing-will-help-prediction-test-sheet', 'Nothing Will Help Prediction Test Sheet', 'cbt'::resource_kind, 'A sheet that treats the thought nothing will help as a prediction, sets up one small test and records the result.', 'Use it to help a client whose hopelessness blocks every suggestion try one thing as an experiment, with support in place.', array['Adults', 'Teens']::text[], 'Full session', 'Complete this in session, not as homework, and check on safety first; if the hopelessness includes thoughts of not wanting to be here, make the safety plan and 988 the first order of business. Then write the thought as a prediction with a confidence rating, pick one small action the client is willing to test this week, and predict exactly what will happen. Record the actual result next session. One partial result is enough to loosen a certainty, so keep the test small.', '[{"id": "f0", "type": "textarea", "label": "The thought, written as a prediction, and how sure I am of it, 0 to 100:"}, {"id": "f1", "type": "textarea", "label": "The one small thing I am willing to test this week:"}, {"id": "f2", "type": "textarea", "label": "What I predict will happen, exactly:"}, {"id": "f3", "type": "textarea", "label": "What actually happened, and what I felt during and after:"}, {"id": "f4", "type": "textarea", "label": "Who I can reach if the week gets very dark, including 988 by call or text:"}]'::jsonb, array['depression', 'predictions', 'behavioral experiment']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('what-lit-me-up-once-reconnection-page', 'What Lit Me Up Once Reconnection Page', 'act'::resource_kind, 'A page that recalls a time the client felt alive and traces the values in it, then plans one small contact with them.', 'Use it to help a client in a flat stretch find the values that used to animate them and touch one again.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask the client to describe, in detail, one time in their life when they felt fully engaged: where they were, who was there, what they were doing with their hands and attention. Then look together for the values in it, such as learning, making, belonging. The goal is not to recreate the memory but to find a thirty-minute version of the value for this week. Clients may grieve the gap between then and now; let that sit before planning.', '[{"id": "f0", "type": "textarea", "label": "A time I felt fully alive, described in detail:"}, {"id": "f1", "type": "textarea", "label": "What I was doing, and who or what I was giving my attention to:"}, {"id": "f2", "type": "textarea", "label": "The values I can see in that memory:"}, {"id": "f3", "type": "textarea", "label": "A small, present-day version of one of those values:"}, {"id": "f4", "type": "textarea", "label": "When I will do it this week, and how I will notice what it does:"}]'::jsonb, array['depression', 'values', 'committed action']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('sadness-opposite-action-posture-card', 'Sadness Opposite Action Posture Card', 'dbt'::resource_kind, 'A card for acting opposite to sadness in the body: head up, shoulders back, eyes forward, a slower fuller breath.', 'Use it to give a client one physical move that runs counter to the pull of low mood.', array['Adults', 'Teens']::text[], 'Five minutes daily for two weeks', 'Teach the posture together and check it is not a brave face: the client is allowed to feel sad while standing like someone who is going to get through the afternoon. Practice it for one minute, then walk across the room in it. Ask the client to use the card at the moments they would usually curl up, and log what happens in mood over the next ten minutes. Make clear this is for ordinary low mood, and that it sits alongside getting active and reaching out, not instead of them.', '[{"id": "f0", "type": "textarea", "label": "The moments in my day when my body curls into the sadness:"}, {"id": "f1", "type": "textarea", "label": "The posture I will take instead: head, shoulders, eyes, breath:"}, {"id": "f2", "type": "textarea", "label": "How I felt before, 0 to 10, and ten minutes after:"}, {"id": "f3", "type": "textarea", "label": "What I did next while holding the posture:"}, {"id": "f4", "type": "textarea", "label": "What I noticed across the two weeks:"}]'::jsonb, array['depression', 'opposite action', 'body awareness']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('pleasant-activity-lottery-draw-game', 'Pleasant Activity Lottery Draw Game', 'game'::resource_kind, 'A group game where players write pleasant activities on slips, draw one at random and commit to it before the next meeting.', 'Use it to get a group with low motivation choosing activities by chance instead of by energy.', array['Groups', 'Adults', 'Teens']::text[], '20 minutes', 'Each player writes three small pleasant activities on slips: things that take under thirty minutes and cost nothing. Pool them, then each player draws one. Rules: a draw can be swapped once, a draw is a commitment to try, and next session each player reports in one sentence. Debrief on what it was like to have the choice made for them, which slips they hoped not to draw, and what the group noticed about activities other members chose.', '[{"id": "f0", "type": "textarea", "label": "The three activities I wrote on my slips:"}, {"id": "f1", "type": "textarea", "label": "What I drew, and whether I wanted to swap it:"}, {"id": "f2", "type": "textarea", "label": "What it was like having the choice made for me:"}, {"id": "f3", "type": "textarea", "label": "Whether I did it, and what it was actually like:"}, {"id": "f4", "type": "textarea", "label": "An activity someone else wrote that I want to try:"}]'::jsonb, array['depression', 'behavioral activation', 'game']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('mail-and-paper-pile-triage-sheet', 'Mail and Paper Pile Triage Sheet', 'worksheet'::resource_kind, 'A sheet for sorting one pile of mail and paper into act, file, shred and ask, with a home for each.', 'Use it to help a client clear one paper pile in a sitting without having to decide about every item in depth.', array['Adults', 'Teens']::text[], '30 minutes', 'Bring one pile to the table in session or on video. Set four spots: act this week, file, shred or recycle, ask someone. Each item gets one touch and goes to a spot; nothing is read in full. Set a timer for fifteen minutes and stop when it rings whether or not the pile is done. Clients often stall on items that need a decision they feel unsure about; those go to ask. Plan where each spot''s contents live afterward so the pile does not reform.', '[{"id": "f0", "type": "textarea", "label": "The pile I am sorting, and how long it has been there:"}, {"id": "f1", "type": "textarea", "label": "Items I need to act on this week, with the first step for each:"}, {"id": "f2", "type": "textarea", "label": "Items to file, and where they will live:"}, {"id": "f3", "type": "textarea", "label": "Items to shred or recycle:"}, {"id": "f4", "type": "textarea", "label": "Items I need to ask someone about, and who:"}, {"id": "f5", "type": "textarea", "label": "Where the next pile will go before it becomes a pile:"}]'::jsonb, array['ADHD', 'executive function', 'planning']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('forgot-again-thought-record', 'Forgot Again Thought Record', 'cbt'::resource_kind, 'A thought record for the moment a client realizes they forgot something, catching the self-judgment before it spreads.', 'Use it to help a client separate the forgotten item from the story about being a hopeless person.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client record the next three times they forget something: what was forgotten, the automatic thought, the feeling and its intensity, and what they did next. Then draft a fairer thought that names the forgetting as a working-memory event with a fix, not a character flaw. Watch for the thought I always do this; count how many things they remembered that day too. The record pairs with whatever external system the client is building.', '[{"id": "f0", "type": "textarea", "label": "What I forgot, and when I realized:"}, {"id": "f1", "type": "textarea", "label": "The first thought I had about myself:"}, {"id": "f2", "type": "textarea", "label": "What I felt, and how strongly, 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "A fairer thought that names what happened and a fix for next time:"}, {"id": "f4", "type": "textarea", "label": "Three things I did remember today:"}]'::jsonb, array['ADHD', 'thought record', 'self-criticism']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('running-late-story-defusion-page', 'Running Late Story Defusion Page', 'act'::resource_kind, 'A page for noticing the I am always late and I let everyone down story and acting on values anyway.', 'Use it to help a client unhook from the lateness story long enough to make the next appointment differently.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to write the story their mind tells on the way to something they are late for, then give it a title, such as the letting everyone down story. Practice saying here is the story again while still walking in the door. Then look at what the client values in showing up: respect, connection, reliability. Plan one concrete change for the next appointment that serves the value, such as leaving when the first alarm sounds, and notice the story show up then too.', '[{"id": "f0", "type": "textarea", "label": "The story my mind tells when I am running late:"}, {"id": "f1", "type": "textarea", "label": "A title for that story:"}, {"id": "f2", "type": "textarea", "label": "What showing up on time serves in my life:"}, {"id": "f3", "type": "textarea", "label": "One concrete change for my next appointment:"}, {"id": "f4", "type": "textarea", "label": "What I will say to myself when the story shows up again:"}]'::jsonb, array['ADHD', 'defusion', 'values']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('waiting-in-line-distress-tolerance-card', 'Waiting in Line Distress Tolerance Card', 'dbt'::resource_kind, 'A card of things to do with mind and body in a line, a waiting room or on hold, when restlessness spikes.', 'Use it to give a client a short menu for the waits that usually end in leaving or snapping.', array['Adults', 'Teens']::text[], '15 minutes to build, then as needed', 'Build the card from the client''s real waits: pharmacy lines, hold music, the school pickup loop. Fill it with five things they can do in under a minute: paced breathing, counting people in blue, naming five sounds, a stretch, a text to a friend. Have them rate the urge to leave before and after a wait this week. Clients with restless bodies often find the counting and noticing items work better than the breathing; let the card reflect that.', '[{"id": "f0", "type": "textarea", "label": "The waits in my week that get under my skin:"}, {"id": "f1", "type": "textarea", "label": "Five things I can do in a line that take under a minute:"}, {"id": "f2", "type": "textarea", "label": "The one I will try first, and when:"}, {"id": "f3", "type": "textarea", "label": "My urge to leave or snap, before and after, 0 to 10:"}, {"id": "f4", "type": "textarea", "label": "What I will swap on the card after a week of using it:"}]'::jsonb, array['ADHD', 'distress tolerance', 'self-soothing']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('tidy-up-song-timer-chart', 'Tidy-Up Song Timer Chart', 'kids'::resource_kind, 'A chart that pairs one song with one tidy-up zone so the task has a start, an end and a beat.', 'Use it to help a parent turn a fight about cleaning up into a three-minute game with music.', array['Children']::text[], '20 minutes to set up, then daily', 'Help the child pick three songs they love and match each to a zone: blocks to the bin for song one, books to the shelf for song two. The parent starts the song, works alongside for the first verse, then steps back and narrates what is done. When the song ends, the tidying stops, finished or not. Keep the chart on the wall with the song names. Avoid adding new zones mid-song; the point is a predictable end.', '[{"id": "f0", "type": "textarea", "label": "My three tidy-up songs:"}, {"id": "f1", "type": "textarea", "label": "Which zone goes with which song:"}, {"id": "f2", "type": "textarea", "label": "What my grown-up does during the first verse:"}, {"id": "f3", "type": "textarea", "label": "What we finished during the songs today:"}, {"id": "f4", "type": "textarea", "label": "A sticker or a mark for each day we did it:"}]'::jsonb, array['ADHD', 'children', 'routines']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('halt-check-card-for-urges', 'HALT Check Card for Urges', 'worksheet'::resource_kind, 'A card that asks hungry, angry, lonely, tired at the moment an urge rises, with one quick response for each.', 'Use it to give a client four fast questions that often explain a sudden urge to use.', array['Adults', 'Teens']::text[], '15 minutes to build, then as needed', 'Go through the four checks and have the client write one quick response for each: a snack they keep on hand, a sentence that names the anger, a person to text, a ten-minute lie-down. Ask them to run the check at the first sign of an urge and before acting on it. Clients often discover that the urge was riding on one of the four and softens when it is handled. The card does not replace their wider plan for urges; it is the first thirty seconds of it.', '[{"id": "f0", "type": "textarea", "label": "Hungry: what I will eat or drink first:"}, {"id": "f1", "type": "textarea", "label": "Angry: how I will name it and to whom:"}, {"id": "f2", "type": "textarea", "label": "Lonely: the person or place I will reach for:"}, {"id": "f3", "type": "textarea", "label": "Tired: what rest I can get in the next hour:"}, {"id": "f4", "type": "textarea", "label": "An urge this week where the check found something, and what happened:"}]'::jsonb, array['addiction', 'urges', 'self-monitoring']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('good-old-days-memory-both-sides-sheet', 'Good Old Days Memory Both Sides Sheet', 'cbt'::resource_kind, 'A sheet that takes a rosy memory of substance use and fills in the parts the memory leaves out.', 'Use it to help a client whose urges are fed by selective memories recall the full picture.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask for the memory that comes up most when the client misses using, in full color. Then ask what happened before it, after it, and the next morning, and who else was in the room and how they fared. Clients are not lying to themselves; the memory is edited, and the sheet restores the cut scenes. Keep the tone respectful of what was genuinely good about those moments, since denying it makes the sheet feel like a sales pitch. Keep the finished sheet for urge moments.', '[{"id": "f0", "type": "textarea", "label": "The memory of using that comes up most when I miss it:"}, {"id": "f1", "type": "textarea", "label": "What was genuinely good about that moment:"}, {"id": "f2", "type": "textarea", "label": "What happened before it, and what the next morning was like:"}, {"id": "f3", "type": "textarea", "label": "Who else was there, and how it went for them:"}, {"id": "f4", "type": "textarea", "label": "The whole picture, in two or three sentences I can read when the urge comes:"}]'::jsonb, array['addiction', 'urges', 'evidence']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('substance-use-shortcut-and-values-detour-map', 'Substance Use Shortcut and Values Detour Map', 'act'::resource_kind, 'A map that draws substance use as the shortcut to a feeling and traces the longer route to the same place through values.', 'Use it to help a client see what substance use has been standing in for and find the slower road there.', array['Adults', 'Teens']::text[], '30 minutes', 'Draw two routes to the same destination. Ask what the client is actually after when the urge arrives: relief, belonging, feeling nothing, feeling something. That is the destination. The shortcut gets them there fast and takes them somewhere else by morning. Map the longer route through values: who they could call, what they could make or do, where they could go. Expect the long road to look unappealing at first; ask which route they would choose for someone they love.', '[{"id": "f0", "type": "textarea", "label": "What I am really after when the urge shows up:"}, {"id": "f1", "type": "textarea", "label": "The shortcut, and where it actually lands me by the next day:"}, {"id": "f2", "type": "textarea", "label": "The longer route to the same feeling, through what I care about:"}, {"id": "f3", "type": "textarea", "label": "What makes the longer route hard to take:"}, {"id": "f4", "type": "textarea", "label": "One step on the longer route I will take this week:"}]'::jsonb, array['addiction', 'values', 'substance use']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('clear-day-self-reward-plan-sheet', 'Clear Day Self-Reward Plan Sheet', 'dbt'::resource_kind, 'A plan for rewarding days without substance use with small, immediate things the client actually enjoys.', 'Use it to help a client reinforce the clear days instead of only bracing against the hard ones.', array['Adults', 'Teens']::text[], '25 minutes', 'List rewards in three sizes: daily (a favorite show, a long shower), weekly (a meal out, a hike), and monthly (something they have wanted). Rules: the reward follows the clear day quickly, it is something the client genuinely likes, and it is never food or money they already need. A slip does not take away rewards already earned. Clients who feel they do not deserve rewards for just not using may need the reinforcement idea explained plainly.', '[{"id": "f0", "type": "textarea", "label": "Small rewards for a clear day, available the same evening:"}, {"id": "f1", "type": "textarea", "label": "A weekly reward for a clear week:"}, {"id": "f2", "type": "textarea", "label": "A monthly reward I have been wanting:"}, {"id": "f3", "type": "textarea", "label": "Who will know about the plan and help me keep to it:"}, {"id": "f4", "type": "textarea", "label": "What I notice about the clear days when they are rewarded:"}]'::jsonb, array['addiction', 'substance use', 'behavioral']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('spot-the-small-decision-story-game', 'Spot the Small Decision Story Game', 'game'::resource_kind, 'A group game where a story is read aloud and players call out each small decision that edged the character toward using.', 'Use it to train a group''s eye for the seemingly unimportant decisions that lead to high-risk moments.', array['Groups', 'Adults', 'Teens']::text[], '25 minutes', 'Read a short story about a character''s ordinary day that ends in a high-risk moment, seeded with small choices: taking the old route home, not charging the phone, agreeing to one quick stop. Players raise a hand at each small decision and earn a point if they can say what the safer version would have been. Play two stories, then have the group write one of their own. Debrief on which decisions were easiest to miss and which ones felt familiar.', '[{"id": "f0", "type": "textarea", "label": "The small decisions I spotted in the story:"}, {"id": "f1", "type": "textarea", "label": "The one I missed that someone else caught:"}, {"id": "f2", "type": "textarea", "label": "A decision in the story that felt familiar from my own week:"}, {"id": "f3", "type": "textarea", "label": "The safer version of that decision:"}, {"id": "f4", "type": "textarea", "label": "The small decision I will watch for in my own day this week:"}]'::jsonb, array['addiction', 'relapse prevention', 'game']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('behind-the-wheel-anger-log', 'Behind the Wheel Anger Log', 'worksheet'::resource_kind, 'A log of anger while driving: the trigger, the thought about the other driver, what the client did, and a cooler option.', 'Use it to help a client whose temper shows up most in traffic see the pattern and plan for it.', array['Adults', 'Teens']::text[], 'One week', 'Ask the client to log each driving flare for a week, filled in after parking, never while moving. Capture the trigger, the thought about the other driver, what their body did, what they did, and a rating. The thoughts are usually about intent and disrespect, which makes the log a good lead into checking attributions. Plan one change for the car: leaving five minutes earlier, a specific playlist, or a sentence to say aloud when cut off.', '[{"id": "f0", "type": "textarea", "label": "What happened on the road, and what I thought about the other driver:"}, {"id": "f1", "type": "textarea", "label": "What my body did, and how angry I was, 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "What I actually did:"}, {"id": "f3", "type": "textarea", "label": "A cooler reading of what the other driver was probably doing:"}, {"id": "f4", "type": "textarea", "label": "One change I will make for the car this week:"}]'::jsonb, array['anger management', 'self-monitoring', 'triggers']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('disrespect-thought-record', 'Disrespect Thought Record', 'cbt'::resource_kind, 'A thought record for moments the client felt disrespected, testing the reading before the anger acts on it.', 'Use it to help a client who hears disrespect in ordinary interactions check the reading first.', array['Adults', 'Teens']::text[], '25 minutes', 'Take two or three recent moments where the client felt disrespected. Record what was said or done, the thought (they think I am nothing), and the anger rating. Then look for other readings: distraction, bad day, a clumsy phrasing, a culture gap. Clients with a long history of being disrespected may find the alternatives insulting at first; validate the history and then ask what fits this particular moment. End with what the client would do under the most likely reading.', '[{"id": "f0", "type": "textarea", "label": "What was said or done, exactly:"}, {"id": "f1", "type": "textarea", "label": "What I took it to mean about how they see me:"}, {"id": "f2", "type": "textarea", "label": "How angry I got, 0 to 10, and what I did:"}, {"id": "f3", "type": "textarea", "label": "Three other things that could explain what they did:"}, {"id": "f4", "type": "textarea", "label": "What I would have done under the most likely reading:"}]'::jsonb, array['anger management', 'thought record', 'thinking traps']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('provoked-moment-choice-point-page', 'Provoked Moment Choice Point Page', 'act'::resource_kind, 'A choice point drawn for the moments a client is provoked, with the toward moves and away moves named in advance.', 'Use it to help a client decide before the next provocation which direction they want to move in.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw the fork: at the bottom, the provocation and the feelings and thoughts it brings; one arrow for away moves (yelling, slamming, cold silence) and one for toward moves that serve the client''s values in that relationship. Fill both in with real examples from the past month. Ask what hooks them hardest at the fork. The page is not about suppressing anger; it is about choosing the move while angry. Carry a photo of it and review the next provocation against it.', '[{"id": "f0", "type": "textarea", "label": "The kind of moment that provokes me most:"}, {"id": "f1", "type": "textarea", "label": "The thoughts and feelings that show up at the fork:"}, {"id": "f2", "type": "textarea", "label": "My usual away moves, and what they cost:"}, {"id": "f3", "type": "textarea", "label": "The toward moves that fit the person I want to be here:"}, {"id": "f4", "type": "textarea", "label": "What hooks me hardest, and how I will notice the fork next time:"}]'::jsonb, array['anger management', 'values', 'committed action']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('cold-water-pause-before-replying-card', 'Cold Water Pause Before Replying Card', 'dbt'::resource_kind, 'A card for a cold water face splash or cold held in the hands before answering when anger is high.', 'Use it to give a client one body-first move that buys thirty seconds before the words come out.', array['Adults', 'Teens']::text[], 'Ten minutes to teach, then as needed', 'Teach the move: when anger is above a seven, say I need a second, go to a sink or a cold drink and hold cold water on the face or in the hands for twenty to thirty seconds, breathing out slowly, then come back. Rehearse the sentence that excuses the client from the room. Check with clients who have heart conditions before using cold on the face, and offer cold hands instead. Log each use for a week with the rating before and after.', '[{"id": "f0", "type": "textarea", "label": "The sentence I will say to step away for a second:"}, {"id": "f1", "type": "textarea", "label": "Where the cold water or cold object is at home, at work and in the car:"}, {"id": "f2", "type": "textarea", "label": "My anger before, 0 to 10, and after the thirty seconds:"}, {"id": "f3", "type": "textarea", "label": "What I said when I came back, compared with what I would have said:"}, {"id": "f4", "type": "textarea", "label": "What got in the way of using it this week:"}]'::jsonb, array['anger management', 'distress tolerance', 'de-escalation']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('raised-voice-signal-and-reset-agreement', 'Raised Voice Signal and Reset Agreement', 'couples'::resource_kind, 'An agreement that names the moment a voice gets loud, a hand signal either partner can use, and what resets the conversation.', 'Use it to give a couple one shared move for the moment volume climbs, before contempt arrives.', array['Couples']::text[], '45 minutes', 'Agree on what counts as raised, since partners usually disagree. Pick a hand signal that means we are getting loud, with a rule that the signal is never argued with. Then set the reset: both partners sit, one minute of silence, a restart with I want to say this more quietly. Each partner says what their part is when they are the loud one and when they are the one signaling. Practice it in session on a mild topic and check in on how it went after two weeks.', '[{"id": "f0", "type": "textarea", "label": "What counts as a raised voice for each of us:"}, {"id": "f1", "type": "textarea", "label": "Our hand signal, and the rule that it is not argued with:"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I will do when I am the one who got loud, and when I am the one signaling:"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I will do when I am the one who got loud, and when I am the one signaling:"}, {"id": "f4", "type": "textarea", "label": "Our reset steps, and the sentence that restarts the conversation:"}]'::jsonb, array['anger management', 'couples', 'de-escalation']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('avoided-objects-and-surfaces-inventory', 'Avoided Objects and Surfaces Inventory', 'worksheet'::resource_kind, 'An inventory of the doorknobs, floors, bins and objects a client avoids touching, with how long each has been avoided.', 'Use it to map the shape of contamination-related avoidance before any practice is planned.', array['Adults', 'Teens']::text[], '30 minutes', 'Walk through home, work and public places with the client and list every object or surface they avoid or handle only with a barrier. Record how long each has been avoided and how distressing touching it would be. Clients often cannot see the whole map until it is written down, and some items will be surprising to them. The inventory is for planning only; nothing on it is touched today. Rank the items afterward and note what life would hold if the top three were ordinary again.', '[{"id": "f0", "type": "textarea", "label": "Objects and surfaces at home I avoid or only touch with a barrier:"}, {"id": "f1", "type": "textarea", "label": "The same list for work, school and public places:"}, {"id": "f2", "type": "textarea", "label": "How long I have been avoiding each, and how distressing touching it would be, 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "What I do instead of touching them, and what it costs:"}, {"id": "f4", "type": "textarea", "label": "What ordinary life would include if the top three were ordinary again:"}]'::jsonb, array['OCD', 'avoidance', 'hierarchy']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('mental-review-tally-and-delay-sheet', 'Mental Review Tally and Delay Sheet', 'cbt'::resource_kind, 'A sheet for tallying episodes of mentally replaying an event to check it was okay, and delaying each replay.', 'Use it to help a client with mental checking see how often it runs and start to put space between the urge and the review.', array['Adults', 'Teens']::text[], 'One week', 'Have the client tally each urge to replay a conversation or event to check for a mistake, with the trigger and the length of the review. Then set a delay rule for the second half of the week: notice the urge, wait ten minutes, and review only if still wanted. Clients frequently describe the review as thinking it through; the tally shows it rarely resolves anything. Note what the doubt did during the delay, which is usually the most useful data on the sheet.', '[{"id": "f0", "type": "textarea", "label": "Each urge to mentally review: the trigger and how long the review lasted:"}, {"id": "f1", "type": "textarea", "label": "What I was checking for, in a sentence:"}, {"id": "f2", "type": "textarea", "label": "Whether the review settled the doubt, and for how long:"}, {"id": "f3", "type": "textarea", "label": "What the doubt did during a ten-minute delay:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the count by the end of the week:"}]'::jsonb, array['OCD', 'intrusive thoughts', 'self-monitoring']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('minutes-reclaimed-from-rituals-ledger', 'Minutes Reclaimed From Rituals Ledger', 'act'::resource_kind, 'A ledger that counts the minutes rituals take in a day and plans what the reclaimed minutes would go to.', 'Use it to connect reducing rituals to the life a client wants the time for.', array['Adults', 'Teens']::text[], '25 minutes', 'Estimate with the client how many minutes each ritual takes on an ordinary day and add them up for the week. Then ask what they would do with that many hours if they appeared, and press for specifics tied to values: calling a sister, reading to a child, learning something. Keep the ledger beside any practice plan so each step has a reason the client chose. Avoid shaming the time spent; the ledger is about what the minutes could buy, not about waste.', '[{"id": "f0", "type": "textarea", "label": "My rituals on an ordinary day, and roughly how many minutes each takes:"}, {"id": "f1", "type": "textarea", "label": "The total for a week:"}, {"id": "f2", "type": "textarea", "label": "What I would do with that time, tied to what I care about:"}, {"id": "f3", "type": "textarea", "label": "The first few minutes I want to reclaim, and the ritual they come from:"}, {"id": "f4", "type": "textarea", "label": "What I will do with those minutes the first time I have them:"}]'::jsonb, array['OCD', 'values', 'committed action']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-disgust-card', 'Opposite Action for Disgust Card', 'dbt'::resource_kind, 'A card for acting opposite to disgust when it does not fit the facts: moving closer, relaxing the face, staying put.', 'Use it to give a client a bodily counter-move for disgust reactions that keep them away from ordinary things.', array['Adults', 'Teens']::text[], '15 minutes to teach, then as needed', 'First check the facts together: is the disgust warranted by real contamination or harm? When it is not, teach the opposite action: unclench the face and shoulders, breathe normally, move a step closer or stay in contact, and let the feeling be there without washing or leaving. Pair the card with items from an inventory the client has already made, starting low. Clients may feel the disgust spike before it drops; tell them to expect that and log how long the spike lasted.', '[{"id": "f0", "type": "textarea", "label": "The situation, and whether the disgust fits the facts:"}, {"id": "f1", "type": "textarea", "label": "What my face and body want to do:"}, {"id": "f2", "type": "textarea", "label": "The opposite moves I will make: face, breath, distance, staying:"}, {"id": "f3", "type": "textarea", "label": "How strong the disgust was at the start, at its peak, and after five minutes:"}, {"id": "f4", "type": "textarea", "label": "What I did instead of washing or leaving:"}]'::jsonb, array['OCD', 'opposite action', 'willingness']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('maybe-is-the-only-answer-game', 'Maybe Is the Only Answer Game', 'game'::resource_kind, 'A group game where every question must be answered with maybe and a reason, practicing sitting with not knowing.', 'Use it to let a group rehearse uncertainty in a playful way before practicing it alone.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Players take turns asking each other questions, from silly (will it rain on Tuesday?) to the kind that pull for reassurance (did I lock the door?). The only legal answer is maybe, followed by one honest reason it could go either way. Giving a yes or no loses a point. Play for ten minutes, then debrief on which questions were hardest to answer with maybe, what the body did while waiting for certainty that never came, and where a maybe would be useful in real life.', '[{"id": "f0", "type": "textarea", "label": "The question that was hardest for me to answer with maybe:"}, {"id": "f1", "type": "textarea", "label": "What my body did when I had to leave it uncertain:"}, {"id": "f2", "type": "textarea", "label": "A maybe someone else gave that I liked:"}, {"id": "f3", "type": "textarea", "label": "Where in my week a maybe would be useful:"}, {"id": "f4", "type": "textarea", "label": "A question I would add to the game:"}]'::jsonb, array['OCD', 'uncertainty', 'game']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('bus-and-train-ride-panic-plan-sheet', 'Bus and Train Ride Panic Plan Sheet', 'worksheet'::resource_kind, 'A plan for riding public transit with panic: the route, the stops, what to do at each stage of a surge, and a return plan.', 'Use it to help a client who avoids buses and trains make one planned ride with a surge plan in hand.', array['Adults', 'Teens']::text[], '30 minutes', 'Pick one real route the client needs. Map the stops, where they will sit or stand, and what they will do in the first minute of a surge: slow the exhale, name five things in the car, let the wave rise without getting off. Agree that getting off early is not failure but is recorded. Many clients plan the ride and skip the plan for the ride home; write both. Debrief the ride next session using the ratings, not just whether it went well.', '[{"id": "f0", "type": "textarea", "label": "The route, the stops, and the day and time I will ride:"}, {"id": "f1", "type": "textarea", "label": "Where I will sit or stand, and what I will have with me:"}, {"id": "f2", "type": "textarea", "label": "The first three things I will do if a surge starts:"}, {"id": "f3", "type": "textarea", "label": "What I will do if I get off early, and how I will get home:"}, {"id": "f4", "type": "textarea", "label": "My highest rating during the ride, and how long the peak lasted:"}]'::jsonb, array['panic attacks', 'exposure', 'planning']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('spin-in-a-chair-sensation-practice-log', 'Spin in a Chair Sensation Practice Log', 'cbt'::resource_kind, 'A log for bringing on dizziness by spinning in a chair on purpose and watching what the sensation does when nobody fights it.', 'Use it to help a client learn that dizziness rises, peaks and passes without becoming the disaster they predict.', array['Adults', 'Teens']::text[], 'Ten minutes daily for one week', 'Do the first round in session: thirty seconds of spinning in a swivel chair, then sit and rate the dizziness every fifteen seconds until it is gone, noting the prediction beforehand. Check for health reasons not to spin before starting. The log tracks each repetition at home with the prediction, the peak, and how long it took to settle. Clients usually find the peak drops and the settle time shortens across the week; have them notice it on the log rather than hearing it from you.', '[{"id": "f0", "type": "textarea", "label": "Before spinning: what I predict will happen, and how sure I am:"}, {"id": "f1", "type": "textarea", "label": "How long I spun, and the peak dizziness, 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "How long it took to settle to a 2:"}, {"id": "f3", "type": "textarea", "label": "What I did while it settled, and whether I fought it:"}, {"id": "f4", "type": "textarea", "label": "What I notice across the week''s log:"}]'::jsonb, array['panic attacks', 'exposure', 'predictions']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('highway-drive-willingness-plan-page', 'Highway Drive Willingness Plan Page', 'act'::resource_kind, 'A page for planning one highway drive with panic along for the ride, with the values the drive serves named first.', 'Use it to help a client who sticks to back roads choose one highway stretch worth being willing for.', array['Adults']::text[], '30 minutes', 'Start with why the highway matters: visiting someone, a job, not planning life around exits. Then pick one stretch between two exits, a time with light traffic, and whether a passenger comes. Rate willingness before the drive, not anxiety. During the drive, the client''s job is to drive and to let the sensations ride in the passenger seat. Plan what they will do if they take the first exit, which is allowed and logged. Review what the drive served, not only how it felt.', '[{"id": "f0", "type": "textarea", "label": "What the highway would give me back if it were ordinary:"}, {"id": "f1", "type": "textarea", "label": "The stretch I will drive, when, and who comes:"}, {"id": "f2", "type": "textarea", "label": "My willingness for this drive, 0 to 10, and what would raise it by one:"}, {"id": "f3", "type": "textarea", "label": "What I will let the panic do while I drive:"}, {"id": "f4", "type": "textarea", "label": "Afterward: what the drive served, and what I will try next:"}]'::jsonb, array['panic attacks', 'willingness', 'values']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('order-the-panic-wave-cards-game', 'Order the Panic Wave Cards Game', 'game'::resource_kind, 'A card-sorting game where teams race to put the stages of a panic surge in order, then argue the edges.', 'Use it to teach a group the arc of a surge so they can place themselves on it the next time one comes.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Make a deck with each stage of a surge on a card: first flutter, catastrophic thought, breathing speeds up, peak, first sign of easing, aftermath. Shuffle, split the group into teams, and time the sort. Then compare orders; disagreements about where the thought goes are the best discussion. Debrief by asking which stage each person finds hardest, where they would place themselves in their last surge, and what knowing the next card does for them.', '[{"id": "f0", "type": "textarea", "label": "The order our team put the cards in:"}, {"id": "f1", "type": "textarea", "label": "Where another team disagreed, and what I think about it:"}, {"id": "f2", "type": "textarea", "label": "The stage of a surge I find hardest:"}, {"id": "f3", "type": "textarea", "label": "Where I was on the cards during my last surge:"}, {"id": "f4", "type": "textarea", "label": "What knowing the next card might change for me:"}]'::jsonb, array['panic attacks', 'psychoeducation', 'game']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('fast-heart-helper-poster-craft', 'Fast Heart Helper Poster Craft', 'kids'::resource_kind, 'A poster a child makes showing the heart as a helper that beats fast to get them ready, not because something is wrong.', 'Use it to give a child and parent a shared picture of a racing heart as a body helper rather than an alarm.', array['Children']::text[], '40 minutes', 'Have the child draw a big heart with a friendly face and arms, and around it the times a heart beats fast on purpose: running, a surprise party, a roller coaster, a scary movie. Then add the times it beats fast when nothing is happening and the words the heart might be saying, such as I am getting you ready, you are okay. The parent helps with the writing and, in a fast-heart moment, points to the poster and names the helper. Hang it where the child gets scared most.', '[{"id": "f0", "type": "textarea", "label": "My heart helper''s name and face:"}, {"id": "f1", "type": "textarea", "label": "Times my heart beats fast on purpose:"}, {"id": "f2", "type": "textarea", "label": "What my heart helper says when it beats fast for no reason:"}, {"id": "f3", "type": "textarea", "label": "Where we hung the poster:"}, {"id": "f4", "type": "textarea", "label": "A time my grown-up pointed to it, and what happened:"}]'::jsonb, array['panic attacks', 'children', 'psychoeducation']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('caregiver-handoff-script-sheet', 'Caregiver Handoff Script Sheet', 'worksheet'::resource_kind, 'A short script for the moment one parent hands the children to the other, covering mood, meals, sleep and one win.', 'Use it to help parents make the handoff informative and warm instead of a dump of complaints at the door.', array['Adults', 'Couples']::text[], '25 minutes', 'Draft the handoff with the parents in four lines: how the kids are right now, what they have eaten and slept, anything coming up, and one good thing that happened. Add a fifth line for the arriving parent: one question, then take over. The usual failure is that the departing parent unloads the whole day as a grievance while the children listen. Rehearse the script in session, and ask the parents to use it for a week and note what changes at the door.', '[{"id": "f0", "type": "textarea", "label": "How the kids are right now, in a sentence:"}, {"id": "f1", "type": "textarea", "label": "What they ate and how they slept:"}, {"id": "f2", "type": "textarea", "label": "Anything coming up in the next few hours:"}, {"id": "f3", "type": "textarea", "label": "One good thing that happened:"}, {"id": "f4", "type": "textarea", "label": "The arriving parent''s one question before taking over:"}]'::jsonb, array['parenting', 'communication', 'routines']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('comparing-myself-to-other-parents-thought-check', 'Comparing Myself to Other Parents Thought Check', 'cbt'::resource_kind, 'A thought check for the moments a parent measures themselves against other parents at school, online or in the family.', 'Use it to help a parent see what the comparison leaves out and what their own child actually needs.', array['Adults']::text[], '25 minutes', 'Collect three recent comparisons: the parent at pickup who seemed calm, the cousin whose child reads early, the post about homemade lunches. For each, write the conclusion the parent drew about themselves, then what they do not know about that family and what they do know about their own child. Comparisons tend to pit the parent''s worst moment against someone else''s best. End with one thing their child needs this week that no comparison can measure.', '[{"id": "f0", "type": "textarea", "label": "Three parents I compared myself to this week, and what I concluded about myself:"}, {"id": "f1", "type": "textarea", "label": "What I do not know about each of those families:"}, {"id": "f2", "type": "textarea", "label": "What I was comparing: my worst moment against what part of theirs:"}, {"id": "f3", "type": "textarea", "label": "What my own child actually needs from me this week:"}, {"id": "f4", "type": "textarea", "label": "One sentence to say to myself at the next pickup:"}]'::jsonb, array['parenting', 'thinking traps', 'self-criticism']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('yelling-hooks-noticing-page-for-parents', 'Yelling Hooks Noticing Page for Parents', 'act'::resource_kind, 'A page for spotting the thoughts that hook a parent into yelling, and the parent they want to be in that same moment.', 'Use it to help a parent catch the hook a beat earlier and choose the move that fits their values.', array['Adults']::text[], '25 minutes', 'Ask for the last three times the parent yelled and the thought right before: they are doing this on purpose, nobody listens to me, I cannot do this. Name each as a hook and notice what the hook pulls them to do. Then ask what kind of parent they want to be in exactly that moment, in a few words, and one move that fits. The page is not about never yelling; it is about seeing the hook. Repair afterward belongs on a separate sheet.', '[{"id": "f0", "type": "textarea", "label": "The last three times I yelled, and the thought right before each:"}, {"id": "f1", "type": "textarea", "label": "What each thought pulled me to do:"}, {"id": "f2", "type": "textarea", "label": "The parent I want to be in that exact moment, in a few words:"}, {"id": "f3", "type": "textarea", "label": "One move that fits that parent when the hook shows up:"}, {"id": "f4", "type": "textarea", "label": "How I will notice the hook a beat earlier next time:"}]'::jsonb, array['parenting', 'defusion', 'values']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('describe-behavior-not-character-parent-card', 'Describe Behavior Not Character Parent Card', 'dbt'::resource_kind, 'A card for turning character labels about a child into plain descriptions of what the child did.', 'Use it to help a parent speak and think about their child''s behavior without the labels that harden over time.', array['Adults']::text[], '20 minutes', 'Collect the labels the parent uses, aloud or silently: lazy, defiant, dramatic, manipulative. For each, write what the child actually did, where and when, in a sentence a camera would agree with. Then say the described version aloud and notice the difference in tone. Parents often object that the label is accurate; agree that the behavior is real and ask what the label does to how they approach the child. The card goes on the fridge for the week.', '[{"id": "f0", "type": "textarea", "label": "The labels I catch myself using about my child:"}, {"id": "f1", "type": "textarea", "label": "For each: what my child actually did, where and when:"}, {"id": "f2", "type": "textarea", "label": "How the described version sounds and feels compared with the label:"}, {"id": "f3", "type": "textarea", "label": "What the label does to how I approach my child:"}, {"id": "f4", "type": "textarea", "label": "One label I will replace this week, and the words I will use instead:"}]'::jsonb, array['parenting', 'validation', 'communication']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('family-secret-handshake-invention-play', 'Family Secret Handshake Invention Play', 'kids'::resource_kind, 'A play session where a child and parent invent a secret handshake to use at goodbyes, reunions and hard moments.', 'Use it to give a child and parent a small physical ritual of connection that belongs only to them.', array['Children']::text[], '20 minutes to invent, then daily', 'The child leads: three to five moves, with a name and a sound if they like. The parent follows the child''s rules, practices it until it is smooth, and suggests when it could be used: school drop-off, bedtime, after a hard moment has settled. Practice at calm times first so it is ready. The handshake is never withheld as a consequence. Siblings can each have their own. Ask the child to draw the steps so the parent remembers them.', '[{"id": "f0", "type": "textarea", "label": "The moves in our handshake, in order:"}, {"id": "f1", "type": "textarea", "label": "Its name and its sound:"}, {"id": "f2", "type": "textarea", "label": "When we will use it:"}, {"id": "f3", "type": "textarea", "label": "A time this week we did it, and how it felt:"}, {"id": "f4", "type": "textarea", "label": "My drawing of the steps so my grown-up remembers:"}]'::jsonb, array['parenting', 'children', 'connection']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('one-handed-self-care-menu', 'One-Handed Self-Care Menu', 'worksheet'::resource_kind, 'A menu of things a new parent can do for themselves with one hand while holding a baby with the other.', 'Use it to help a new parent find care that fits the actual shape of their days instead of waiting for free time.', array['Adults']::text[], '20 minutes', 'Build the menu from what the parent already likes, cut down to one-handed and interruptible: a podcast episode, a cup of something warm, a text thread with a friend, five slow breaths with eyes closed, stepping into the yard. Aim for ten items. Clients often say nothing counts unless it is a full hour alone; the menu is the argument against that. Ask them to use two items a day and mark them, and to notice what the small moments do to the day.', '[{"id": "f0", "type": "textarea", "label": "Things I enjoy that I could do with one hand:"}, {"id": "f1", "type": "textarea", "label": "Things that take under five minutes and can be interrupted:"}, {"id": "f2", "type": "textarea", "label": "My menu of ten, written out:"}, {"id": "f3", "type": "textarea", "label": "The two I will do today:"}, {"id": "f4", "type": "textarea", "label": "What I notice after a week of two a day:"}]'::jsonb, array['perinatal and postpartum', 'self-care', 'pacing']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('bad-parent-label-check-sheet', 'Bad Parent Label Check Sheet', 'cbt'::resource_kind, 'A sheet for the thought I am a bad parent, checking it against what a bad parent would actually do and what this parent did.', 'Use it to help a new parent separate a hard moment from a verdict on who they are.', array['Adults']::text[], '25 minutes', 'Write the moment the thought arrived: the baby cried for an hour, the parent felt nothing, the parent snapped at their partner. Then ask what a genuinely bad parent would do in that moment and compare it with what the client did, including the fact that they are sitting here worrying about it. If the moment included thoughts of harm toward themselves or the baby, pause the sheet, address safety together, and name 988 before going on. Finish with a fairer sentence.', '[{"id": "f0", "type": "textarea", "label": "The moment that brought the thought I am a bad parent:"}, {"id": "f1", "type": "textarea", "label": "What a genuinely bad parent would do in that moment:"}, {"id": "f2", "type": "textarea", "label": "What I actually did, including afterward:"}, {"id": "f3", "type": "textarea", "label": "What the thought leaves out about my week:"}, {"id": "f4", "type": "textarea", "label": "A fairer sentence, and who I can call if the thoughts turn dark, including 988 by call or text:"}]'::jsonb, array['perinatal and postpartum', 'self-criticism', 'thinking traps']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('new-parent-identity-timeline-page', 'New Parent Identity Timeline Page', 'act'::resource_kind, 'A timeline of who the client was before the baby, who they are now, and the values that run through both.', 'Use it to help a new parent grieve what has changed while finding the thread that has not.', array['Adults']::text[], '40 minutes', 'Draw a line with before on the left and now on the right. Ask the client to mark roles, routines and pleasures from before, then what has filled the days since. Many will see a long list of losses; let that be said. Then look for the values that appear on both sides, such as care, humor, learning, and name one way each is showing up now, however small. End by placing one thing from the left side they want to carry forward in the next three months.', '[{"id": "f0", "type": "textarea", "label": "Who I was before the baby: roles, routines, things I loved:"}, {"id": "f1", "type": "textarea", "label": "Who I am now: how my days actually go:"}, {"id": "f2", "type": "textarea", "label": "What I miss most, said plainly:"}, {"id": "f3", "type": "textarea", "label": "The values I can see on both sides of the line:"}, {"id": "f4", "type": "textarea", "label": "One thing from before I will bring forward in the next three months, in a size that fits now:"}]'::jsonb, array['perinatal and postpartum', 'values', 'acceptance']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('dear-man-ask-for-help-with-the-baby-sheet', 'DEAR MAN Ask for Help With the Baby Sheet', 'dbt'::resource_kind, 'A DEAR MAN script for asking a partner, relative or friend for a specific kind of help with the baby.', 'Use it to help a new parent make one clear ask instead of hoping someone notices they are drowning.', array['Adults']::text[], '25 minutes', 'Pick the single most useful help the client could receive this week and the person who could give it. Build the script: describe the situation, express the feeling, assert the request, reinforce what it gives the other person, then stay mindful, appear confident, negotiate if needed. Rehearse it aloud. New parents often shrink the ask until it is useless; keep it specific, such as take the baby from six to seven so I can shower and sit down. Log the response.', '[{"id": "f0", "type": "textarea", "label": "Describe: the situation in facts:"}, {"id": "f1", "type": "textarea", "label": "Express: how I feel about it:"}, {"id": "f2", "type": "textarea", "label": "Assert: exactly what I am asking for, and when:"}, {"id": "f3", "type": "textarea", "label": "Reinforce: what it would give them or us:"}, {"id": "f4", "type": "textarea", "label": "What I will say if they push back, and what happened when I asked:"}]'::jsonb, array['perinatal and postpartum', 'DEAR MAN', 'support']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('closeness-after-baby-small-steps-plan', 'Closeness After Baby Small Steps Plan', 'couples'::resource_kind, 'A plan for rebuilding physical and emotional closeness after a baby in steps both partners choose, with no pressure toward sex.', 'Use it to help partners talk about closeness after birth and agree on steps that fit where each of them is.', array['Couples']::text[], 'Full session', 'Have each partner describe what closeness means to them right now and what gets in the way: exhaustion, body changes, feeling like coworkers, worry about pain. Then build a ladder of small steps from a hand held on the couch to whatever each is ready for, with the clear rule that any step can be declined without a reason and that sex is not the finish line. Each partner names their part. Check in after two weeks on what felt good, not on how far they got.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what closeness means to me right now, and what gets in the way:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what closeness means to me right now, and what gets in the way:"}, {"id": "f2", "type": "textarea", "label": "The small steps we both feel ready for, in order:"}, {"id": "f3", "type": "textarea", "label": "Our rule about declining a step, in our own words:"}, {"id": "f4", "type": "textarea", "label": "What each of us will do this week, and when we will talk about how it felt:"}]'::jsonb, array['perinatal and postpartum', 'couples', 'connection']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('promises-to-myself-kept-tally-sheet', 'Promises to Myself Kept Tally Sheet', 'worksheet'::resource_kind, 'A tally of small promises a client makes to themselves and keeps, building a record of being someone they can count on.', 'Use it to help a client who trusts everyone''s word but their own rebuild self-trust in small kept promises.', array['Adults', 'Teens']::text[], 'Two weeks', 'Ask for one small promise a day, so small it is almost silly: drink a glass of water before coffee, text one friend, put the shoes away. Tally kept and missed without comment. The point is the record, not the tasks; clients with low self-regard often have a long history of grand promises broken and no record of small ones kept. At the end, read the tally together and ask what it says about whether they can count on themselves. Scale up slowly.', '[{"id": "f0", "type": "textarea", "label": "Today''s small promise to myself:"}, {"id": "f1", "type": "textarea", "label": "Kept or missed, with no commentary:"}, {"id": "f2", "type": "textarea", "label": "The pattern I notice by the end of week one:"}, {"id": "f3", "type": "textarea", "label": "What the tally says about whether I can count on myself:"}, {"id": "f4", "type": "textarea", "label": "The slightly bigger promise I am ready to make for week three:"}]'::jsonb, array['self-esteem', 'habits', 'self-monitoring']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('positive-feedback-deflection-catch-sheet', 'Positive Feedback Deflection Catch Sheet', 'cbt'::resource_kind, 'A sheet for catching the moment a client deflects praise, naming the thought behind the deflection and trying a plain thank you.', 'Use it to help a client who argues with every compliment let one land and see what happens.', array['Adults', 'Teens']::text[], '20 minutes', 'Log three recent moments of praise: what was said, what the client replied, and the thought behind the reply, such as they are just being nice or they do not know the real me. Then write the response they will try next time, usually a plain thank you with nothing added. Have them predict how the other person will react, then test it. Clients often fear a plain thank you will sound arrogant; the sheet lets them find out. Keep the compliments themselves as evidence.', '[{"id": "f0", "type": "textarea", "label": "Three things people said to me recently that were positive:"}, {"id": "f1", "type": "textarea", "label": "What I said back, and the thought behind it:"}, {"id": "f2", "type": "textarea", "label": "What I predict will happen if I just say thank you:"}, {"id": "f3", "type": "textarea", "label": "What actually happened when I tried it:"}, {"id": "f4", "type": "textarea", "label": "The compliments, written down as evidence I can reread:"}]'::jsonb, array['self-esteem', 'evidence', 'behavioral experiment']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('approval-versus-values-choice-point-page', 'Approval Versus Values Choice Point Page', 'act'::resource_kind, 'A choice point for the moments a client bends toward approval, with the move toward their own values beside it.', 'Use it to help a client see when they are choosing to be liked over being themselves and decide on purpose.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw the fork: the moment someone''s approval is on the line, the thoughts and feelings that show up, the approval move (agreeing, shrinking, over-apologizing) and the values move. Fill it with three real moments from the month. Note that the approval move is not wrong; the question is whether it is chosen or automatic. Ask what the values move would cost and what it would give. Plan one small values move for a low-stakes moment this week.', '[{"id": "f0", "type": "textarea", "label": "Three recent moments where someone''s approval was on the line:"}, {"id": "f1", "type": "textarea", "label": "What I thought and felt at the fork:"}, {"id": "f2", "type": "textarea", "label": "My approval moves, and what they cost me:"}, {"id": "f3", "type": "textarea", "label": "The values move in each moment, and what it would have given me:"}, {"id": "f4", "type": "textarea", "label": "One low-stakes moment this week where I will try the values move:"}]'::jsonb, array['self-esteem', 'values', 'committed action']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('loving-kindness-toward-myself-script-card', 'Loving Kindness Toward Myself Script Card', 'dbt'::resource_kind, 'A short loving kindness script aimed at the self, built in the client''s own words, for a daily three-minute practice.', 'Use it to give a client who finds self-compassion hollow a scripted practice that grows familiar with repetition.', array['Adults', 'Teens']::text[], 'Three minutes daily for two weeks', 'Start the practice with someone the client finds easy to wish well, then move the same phrases to themselves: may I be safe, may I be at ease, may I be kind to myself today. Let them rewrite the phrases until they can say them without wincing, even if they do not believe them yet. Expect resistance and log it rather than fighting it. Clients who cannot start with themselves can picture themselves as a child or hear the phrases in a kind friend''s voice.', '[{"id": "f0", "type": "textarea", "label": "The person I wished well first, and the phrases I used:"}, {"id": "f1", "type": "textarea", "label": "My phrases for myself, in words I can say:"}, {"id": "f2", "type": "textarea", "label": "What came up when I turned the phrases toward myself:"}, {"id": "f3", "type": "textarea", "label": "What helped: a photo, a child''s version of me, a friend''s voice:"}, {"id": "f4", "type": "textarea", "label": "How the practice felt on day one compared with day fourteen:"}]'::jsonb, array['self-esteem', 'self-compassion', 'mindfulness']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('brag-minute-timer-game', 'Brag Minute Timer Game', 'game'::resource_kind, 'A group game where each player gets sixty seconds to brag without a single qualifier while the group counts the hedges.', 'Use it to let a group practice saying what they are good at out loud and notice how hard the hedging is to drop.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'One player at a time takes the chair with a timer. For sixty seconds they talk about things they do well; every but, kind of, I guess or shrug costs a point, counted by the group. Applause at the end is mandatory. Debrief on what it felt like in the body to hold the floor, which hedges slipped out most, and what the group noticed about people''s faces while listening. Players who freeze can be given a prompt by the group.', '[{"id": "f0", "type": "textarea", "label": "What I bragged about:"}, {"id": "f1", "type": "textarea", "label": "The hedges I caught myself using:"}, {"id": "f2", "type": "textarea", "label": "What my body did while I held the floor:"}, {"id": "f3", "type": "textarea", "label": "What I noticed on other people''s faces while they listened:"}, {"id": "f4", "type": "textarea", "label": "One brag I will say to someone outside the group this week:"}]'::jsonb, array['self-esteem', 'strengths', 'game']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('camera-on-video-call-steps-sheet', 'Camera On Video Call Steps Sheet', 'worksheet'::resource_kind, 'A stepped plan for turning the camera on in video calls, from a small meeting to speaking with the camera on in a large one.', 'Use it to help a client who hides behind a black square work up to being seen on screen.', array['Adults', 'Teens']::text[], 'Two weeks', 'List the client''s regular calls and rank them by how exposed being on camera feels. Build steps: camera on for the first minute of a small call, on for the whole call, on while speaking, on in the large meeting. Pair each step with a prediction and a result. Clients often watch themselves on screen the whole time; add the step of hiding their own tile. Review what others actually did when the camera came on, which is usually nothing.', '[{"id": "f0", "type": "textarea", "label": "My regular calls, ranked by how exposed being on camera would feel:"}, {"id": "f1", "type": "textarea", "label": "My steps, from easiest to hardest:"}, {"id": "f2", "type": "textarea", "label": "Before each step: what I predict others will notice or do:"}, {"id": "f3", "type": "textarea", "label": "What actually happened, including whether I watched my own tile:"}, {"id": "f4", "type": "textarea", "label": "What I will try next week:"}]'::jsonb, array['social anxiety', 'exposure', 'predictions']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('hosting-a-small-gathering-prediction-sheet', 'Hosting a Small Gathering Prediction Sheet', 'cbt'::resource_kind, 'A prediction sheet for hosting two or three people, written before and scored after the gathering.', 'Use it to help a client who never hosts test the predictions that keep the door closed.', array['Adults', 'Teens']::text[], 'One week', 'Plan the smallest gathering the client could host: two friends for an hour. Write every prediction beforehand: the silences, the mess being judged, the guests leaving early, the client blanking. Rate each. After the gathering, score each prediction against what happened and ask the guests nothing; the test is of the predictions, not of the guests'' manners. The sheet often shows the client spent the hour grading themselves rather than hosting, which is the next target.', '[{"id": "f0", "type": "textarea", "label": "Who I will invite, when, and for how long:"}, {"id": "f1", "type": "textarea", "label": "My predictions, each rated for how sure I am, 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "What actually happened, prediction by prediction:"}, {"id": "f3", "type": "textarea", "label": "How much of the hour I spent watching myself instead of my guests:"}, {"id": "f4", "type": "textarea", "label": "What I will do differently next time, and when:"}]'::jsonb, array['social anxiety', 'predictions', 'behavioral experiment']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('hide-or-show-up-choice-point-page', 'Hide or Show Up Choice Point Page', 'act'::resource_kind, 'A choice point for the moment a client could hide (cancel, stay quiet, leave early) or show up, with values on the showing-up side.', 'Use it to help a client who hides automatically make the hiding a choice and see what showing up serves.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw the fork at a specific upcoming event. On the hide side, list the moves the client knows well: canceling, standing by the wall, scrolling, leaving at the first lull. On the show-up side, list the moves that fit what they value about friendship or work. Name the thoughts and feelings at the fork without arguing with them. The client chooses which fork to take at the event, knowing both, and reports back on the choice rather than on the anxiety level.', '[{"id": "f0", "type": "textarea", "label": "The upcoming event, and what I value that is connected to it:"}, {"id": "f1", "type": "textarea", "label": "My hide moves, in detail:"}, {"id": "f2", "type": "textarea", "label": "My show-up moves that fit those values:"}, {"id": "f3", "type": "textarea", "label": "The thoughts and feelings that show up at the fork:"}, {"id": "f4", "type": "textarea", "label": "Which fork I took, and what showing up or hiding gave me:"}]'::jsonb, array['social anxiety', 'values', 'willingness']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('half-smile-entering-the-room-card', 'Half Smile Entering the Room Card', 'dbt'::resource_kind, 'A card for walking into a room with a half smile and willing hands, letting the body lead the mind.', 'Use it to give a client one bodily move for the doorway moment when every eye seems to turn.', array['Adults', 'Teens']::text[], 'Ten minutes to teach, then as needed', 'Teach the half smile: lips slightly turned up, face relaxed, hands open at the sides, shoulders down. Practice it walking through the therapy room door three times. Explain that the body posture tends to soften the mind''s read of the room and that the client does not have to feel it first. Then set three doorways this week to try it. Log the thought at the doorway, the posture, and what the first thirty seconds in the room were like compared with usual.', '[{"id": "f0", "type": "textarea", "label": "The doorways this week where every eye seems to turn:"}, {"id": "f1", "type": "textarea", "label": "My posture at the door: face, hands, shoulders:"}, {"id": "f2", "type": "textarea", "label": "The thought at the doorway, and what I did with it:"}, {"id": "f3", "type": "textarea", "label": "What the first thirty seconds in the room were like compared with usual:"}, {"id": "f4", "type": "textarea", "label": "What I will change about the card after a week:"}]'::jsonb, array['social anxiety', 'mindfulness', 'distress tolerance']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('brave-voice-volume-dial-craft', 'Brave Voice Volume Dial Craft', 'kids'::resource_kind, 'A cardboard dial a child makes with voice volumes from whisper to playground, used to practice a brave speaking volume.', 'Use it to help a quiet child and their parent practice being heard without being told to speak up.', array['Children']::text[], '30 minutes', 'Make a dial with five settings: mouse, library, kitchen table, classroom, playground. The child practices saying their name and one sentence at each setting, and the parent guesses the setting with eyes closed. Then agree which setting is the brave voice for ordering at a counter or answering a teacher. The parent never says speak up; they ask what number the child is on and what number the moment needs. Celebrate reaching the number, not loudness itself.', '[{"id": "f0", "type": "textarea", "label": "My five voice settings, with pictures:"}, {"id": "f1", "type": "textarea", "label": "The setting my grown-up guessed for each try:"}, {"id": "f2", "type": "textarea", "label": "The brave voice number for ordering, for class, and for a new friend:"}, {"id": "f3", "type": "textarea", "label": "A time this week I used my brave voice number:"}, {"id": "f4", "type": "textarea", "label": "What my grown-up said instead of speak up:"}]'::jsonb, array['social anxiety', 'children', 'craft']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('dreams-about-them-notes-page', 'Dreams About Them Notes Page', 'worksheet'::resource_kind, 'A page for noting dreams about the person who died, what the client woke feeling, and what they did with the morning.', 'Use it to give a grieving client a place to hold the dreams that leave them raw, without having to interpret them.', array['Adults', 'Teens']::text[], 'Ongoing', 'Offer the page for the mornings after a dream, with the plain instruction to write what they remember if they want to, how they felt on waking, and what helped in the first hour. Make clear there is nothing to decode; some dreams are comforting and some are hard, and both are common. If dreams are leaving the client unable to function or are mostly distressing, talk about sleep and pacing rather than about content. Review the page only if the client brings it.', '[{"id": "f0", "type": "textarea", "label": "What I remember of the dream, as much or as little as I want:"}, {"id": "f1", "type": "textarea", "label": "How I felt when I woke:"}, {"id": "f2", "type": "textarea", "label": "What helped in the first hour:"}, {"id": "f3", "type": "textarea", "label": "Whether the dream was mostly comforting, mostly hard, or mixed:"}, {"id": "f4", "type": "textarea", "label": "Anything I want to tell my therapist about it:"}]'::jsonb, array['grief and loss', 'sleep', 'pacing']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('fear-of-forgetting-them-thought-check', 'Fear of Forgetting Them Thought Check', 'cbt'::resource_kind, 'A thought check for the fear that healing means forgetting the person, with the evidence from the client''s own week.', 'Use it to help a client who holds onto pain as proof of love look at what memory actually does over time.', array['Adults', 'Teens']::text[], '25 minutes', 'Write the fear as a prediction: if I feel better, I will forget them. Then gather this week''s evidence: the times the client thought of the person, what triggered the memories, what they still do because of them. Ask what forgetting would actually mean and whether anyone they know has forgotten someone they loved. The fear usually turns out to be about losing the sharpness, which is different from losing the person. End with a sentence that holds both.', '[{"id": "f0", "type": "textarea", "label": "The fear, written as a prediction:"}, {"id": "f1", "type": "textarea", "label": "The times this week I thought of them, and what brought them to mind:"}, {"id": "f2", "type": "textarea", "label": "What I still do, say or choose because of them:"}, {"id": "f3", "type": "textarea", "label": "What forgetting would actually mean, and whether I know anyone it has happened to:"}, {"id": "f4", "type": "textarea", "label": "A sentence that holds both the easing and the remembering:"}]'::jsonb, array['grief and loss', 'predictions', 'evidence']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('what-they-would-want-choice-point-page', 'What They Would Want Choice Point Page', 'act'::resource_kind, 'A choice point for a decision the client is stuck on, asking what the person they lost would want and what the client values.', 'Use it to help a grieving client use their bond with the person as a compass without being frozen by it.', array['Adults', 'Teens']::text[], '30 minutes', 'Pick one decision the client has been circling: going back to work, selling the house, saying yes to a trip. Draw the fork and at the bottom write the grief and guilt that show up. Then ask two questions: what would they have wanted for you, and what do you value here. Sometimes the answers differ, and the client gets to notice that their own values count. Watch for guilt masquerading as loyalty. Plan one small step toward the chosen fork.', '[{"id": "f0", "type": "textarea", "label": "The decision I keep circling:"}, {"id": "f1", "type": "textarea", "label": "The grief and guilt that show up when I face it:"}, {"id": "f2", "type": "textarea", "label": "What they would have wanted for me, honestly:"}, {"id": "f3", "type": "textarea", "label": "What I value here, in my own words:"}, {"id": "f4", "type": "textarea", "label": "Where the two answers agree or differ, and one small step toward the fork I choose:"}]'::jsonb, array['grief and loss', 'values', 'committed action']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('paced-photo-album-viewing-plan', 'Paced Photo Album Viewing Plan', 'dbt'::resource_kind, 'A plan for looking at photos of the person who died in small sittings the client sets, with a skill before, during and after.', 'Use it to help a client approach the photos they have been avoiding, or drowning in, at a pace they control.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask whether the client has been avoiding the photos entirely or sitting in them for hours; the plan works for both. Set a sitting: five photos, ten minutes, a timer. Pick a skill for before (paced breathing), during (describe, do not judge), and after (self-soothe with something warm). Agree who they will tell afterward. Clients often find the first sitting easier than feared and the third harder; that is ordinary. Adjust the size of the sitting, not the plan.', '[{"id": "f0", "type": "textarea", "label": "Whether I have been avoiding the photos or losing hours in them:"}, {"id": "f1", "type": "textarea", "label": "My sitting: how many photos, how long, and when:"}, {"id": "f2", "type": "textarea", "label": "My skill before, during and after:"}, {"id": "f3", "type": "textarea", "label": "Who I will tell afterward:"}, {"id": "f4", "type": "textarea", "label": "How each sitting went, and what I will change about its size:"}]'::jsonb, array['grief and loss', 'distress tolerance', 'pacing']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('memory-pillowcase-decorating-craft', 'Memory Pillowcase Decorating Craft', 'kids'::resource_kind, 'A plain pillowcase a child decorates with fabric markers in memory of someone who died, to sleep on or keep.', 'Use it to give a grieving child something soft they made that holds the person close at night.', array['Children']::text[], 'One hour', 'Give the child a plain pillowcase and fabric markers and invite them to draw the person, things they did together, or just colors and words that feel like them. The parent draws alongside on a corner, talks about the person by name, and follows the child''s lead on what gets said. Some children want it on their bed and some want it in a drawer; both are fine. Tell the parent that tears while drawing are expected and that it is okay to stop and finish another day.', '[{"id": "f0", "type": "textarea", "label": "Who the pillowcase is for:"}, {"id": "f1", "type": "textarea", "label": "What I drew or wrote on it:"}, {"id": "f2", "type": "textarea", "label": "What my grown-up drew in the corner:"}, {"id": "f3", "type": "textarea", "label": "Where I want to keep it:"}, {"id": "f4", "type": "textarea", "label": "A memory of them we talked about while we worked:"}]'::jsonb, array['grief and loss', 'children', 'craft']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('friendship-drift-reflection-sheet', 'Friendship Drift Reflection Sheet', 'worksheet'::resource_kind, 'A sheet for a friendship that has quietly faded, sorting what changed, what the client wants and the first reach if any.', 'Use it to help a client decide whether a drifting friendship is worth a reach, a release or a redefinition.', array['Adults', 'Teens']::text[], '30 minutes', 'Name the friend and when the client last felt close. Then list what changed: a move, a baby, a slight, a season. Ask what they miss and what they do not, and what the friendship would need to look like now. Clients often assume drift means the friend chose to leave; the sheet separates drift from rejection. End with one of three choices: a reach with a specific message, a release with a kind thought, or a redefinition as an occasional friend.', '[{"id": "f0", "type": "textarea", "label": "The friend, and when I last felt close to them:"}, {"id": "f1", "type": "textarea", "label": "What changed, as far as I can tell:"}, {"id": "f2", "type": "textarea", "label": "What I miss about the friendship, and what I do not:"}, {"id": "f3", "type": "textarea", "label": "What it would need to look like now to work for me:"}, {"id": "f4", "type": "textarea", "label": "Reach, release or redefine: my choice, and the first step if I am reaching:"}]'::jsonb, array['relationship issues', 'decisions', 'connection']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('all-or-nothing-relationship-thought-check', 'All or Nothing Relationship Thought Check', 'cbt'::resource_kind, 'A thought check for sweeping verdicts on a relationship, such as this never works or they always do this, against the week''s record.', 'Use it to help a client whose view of a relationship swings to extremes look at the mixed middle.', array['Adults', 'Teens']::text[], '25 minutes', 'Collect the week''s always and never statements about the partner, friend or parent. For each, count the actual instances both ways over the past month. Then place the relationship on a line between all bad and all good and ask what the realistic point tells them to do. Clients in distress often judge the whole relationship by the last argument; the count resists that. The sheet is not for deciding to stay or go, only for seeing accurately before deciding.', '[{"id": "f0", "type": "textarea", "label": "My always and never statements about this relationship this week:"}, {"id": "f1", "type": "textarea", "label": "For each: how many times it actually happened this month, and how many times the opposite did:"}, {"id": "f2", "type": "textarea", "label": "Where the relationship honestly sits on a line from all bad to all good:"}, {"id": "f3", "type": "textarea", "label": "What the last argument made me forget:"}, {"id": "f4", "type": "textarea", "label": "What the realistic picture suggests I do next:"}]'::jsonb, array['relationship issues', 'thinking traps', 'evidence']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('jealousy-triggers-talk-sheet', 'Jealousy Triggers Talk Sheet', 'couples'::resource_kind, 'A sheet where the jealous partner names their triggers and the other partner says what is actually happening, with one agreement each.', 'Use it to help a couple talk about jealousy as a shared problem rather than an accusation or a character flaw.', array['Couples']::text[], 'Full session', 'The partner who feels jealous lists the moments that set it off: a late text, a coworker''s name, a phone face down. The other partner says what is happening on their side at those moments, without defending. Then look at what the jealousy is protecting, usually a fear of being replaced or a past betrayal, and name it. Each partner makes one agreement: the jealous partner about what they will do with the feeling, the other about one small transparency they can offer freely.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the moments that set off my jealousy, and what I imagine in them:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what is actually happening on my side in those moments:"}, {"id": "f2", "type": "textarea", "label": "What the jealousy is protecting, in both our words:"}, {"id": "f3", "type": "textarea", "label": "Partner A: what I will do with the feeling before I act on it:"}, {"id": "f4", "type": "textarea", "label": "Partner B: one small openness I can offer freely, not under pressure:"}]'::jsonb, array['relationship issues', 'couples', 'safety']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('asking-intensity-dial-sheet', 'Asking Intensity Dial Sheet', 'dbt'::resource_kind, 'A dial from one to ten for how firmly to ask or how firmly to say no, set by weighing the factors before the conversation.', 'Use it to help a client who always asks at a two or always at a ten pick the intensity that fits this situation.', array['Adults', 'Teens']::text[], '25 minutes', 'Take one upcoming ask or refusal. Walk through the factors: the client''s rights and the other''s, how capable the other is of giving it, timing, the relationship''s history, what the client has given lately, and self-respect. Each factor nudges the dial up or down. Then set the number and write the words at that intensity. Clients are often surprised that the factors point to a five when they were planning a nine or a one. Rehearse the words at that volume.', '[{"id": "f0", "type": "textarea", "label": "The ask or refusal I am preparing for:"}, {"id": "f1", "type": "textarea", "label": "The factors that turn the dial up:"}, {"id": "f2", "type": "textarea", "label": "The factors that turn the dial down:"}, {"id": "f3", "type": "textarea", "label": "The number I land on, 1 to 10, and why:"}, {"id": "f4", "type": "textarea", "label": "What I will say at that intensity, and how it went:"}]'::jsonb, array['relationship issues', 'interpersonal effectiveness', 'assertiveness']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('guess-my-answer-partner-game', 'Guess My Answer Partner Game', 'game'::resource_kind, 'A game where partners predict each other''s answers to everyday questions and score how well each knows the other.', 'Use it to show a couple where they know each other well and where they have stopped asking, with laughter instead of blame.', array['Couples', 'Groups']::text[], '30 minutes', 'Prepare twenty questions from light (favorite breakfast) to deeper (what they are most worried about this month). Each partner writes their own answer and their guess of the other''s; reveal and score a point for each match. Rules: no arguing with the other person''s own answer, and a wrong guess earns a one-sentence explanation from the partner. Debrief on which misses surprised them, which questions they stopped asking years ago, and one they will ask again this week.', '[{"id": "f0", "type": "textarea", "label": "Our score, and the questions we matched on:"}, {"id": "f1", "type": "textarea", "label": "The miss that surprised me most:"}, {"id": "f2", "type": "textarea", "label": "What I learned about my partner''s answer that I did not know:"}, {"id": "f3", "type": "textarea", "label": "A question I realized I stopped asking a long time ago:"}, {"id": "f4", "type": "textarea", "label": "One question I will ask my partner again this week:"}]'::jsonb, array['relationship issues', 'game', 'connection']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('family-gathering-safety-plan-sheet', 'Family Gathering Safety Plan Sheet', 'worksheet'::resource_kind, 'A plan for a family gathering where someone the client wants distance from may be present, covering support, exits and the day after.', 'Use it to help a client decide whether to attend and, if so, go with a plan that keeps them steady.', array['Adults', 'Teens']::text[], '40 minutes', 'Start with whether the client wants to go at all; not going is a complete plan. If they attend, map the support person, the seating, the rooms they will use, a reason to leave that needs no explanation, and a check-in text at a set time. Plan the evening after, since the crash often comes then. The sheet stays on logistics and safety and never asks what happened in the past. Keep a copy, and review how it went in the next session.', '[{"id": "f0", "type": "textarea", "label": "Whether I want to attend, and what going or not going would cost me:"}, {"id": "f1", "type": "textarea", "label": "My support person, and how they will know I need them:"}, {"id": "f2", "type": "textarea", "label": "Where I will sit, which rooms I will use, and my reason to leave that needs no explanation:"}, {"id": "f3", "type": "textarea", "label": "The time I will check in by text, and with whom:"}, {"id": "f4", "type": "textarea", "label": "What I will do that evening to settle, and who I can call if it is hard, including 988 by call or text:"}]'::jsonb, array['sexual abuse', 'safety', 'planning']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('flinch-reaction-thought-check-sheet', 'Flinch Reaction Thought Check Sheet', 'cbt'::resource_kind, 'A sheet for the self-critical thoughts after a flinch, freeze or startle, replaced with a plain account of what the body did.', 'Use it to help a client stop reading their body''s protective reactions as evidence that something is wrong with them.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask for a recent moment when the client flinched or froze: a hand on the shoulder, a raised voice in a store. Record what the body did and the thought that followed, often I am broken or I should be over this. Then write what the body was actually doing, protecting them fast, and a fair sentence about it. The sheet never asks why the body learned this or what happened; it stays in the present reaction. Pair with a grounding step for the moments after a flinch.', '[{"id": "f0", "type": "textarea", "label": "A recent moment I flinched, froze or startled:"}, {"id": "f1", "type": "textarea", "label": "What my body did, in plain words:"}, {"id": "f2", "type": "textarea", "label": "The thought I had about myself right after:"}, {"id": "f3", "type": "textarea", "label": "What my body was actually doing for me:"}, {"id": "f4", "type": "textarea", "label": "A fair sentence about the reaction, and one grounding step for the minute after:"}]'::jsonb, array['sexual abuse', 'stabilizing', 'self-criticism']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('spacing-out-noticing-and-return-card', 'Spacing Out Noticing and Return Card', 'dbt'::resource_kind, 'A card for noticing the early signs of spacing out and returning with a step the client picked in advance.', 'Use it to give a client who drifts away under stress a planned route back to the room.', array['Adults', 'Teens']::text[], '15 minutes to build, then as needed', 'Build the card from the client''s own early signs: sounds going distant, a cold feeling, staring, losing the thread of a conversation. Then pick two or three return steps: feet pressed to the floor, cold water on the wrists, naming objects by color, saying the date aloud. Practice the steps while present so they are familiar. The card is about coming back, not about what the mind drifted from; if content surfaces, slow down and ground first. Review which steps worked.', '[{"id": "f0", "type": "textarea", "label": "My early signs that I am starting to drift:"}, {"id": "f1", "type": "textarea", "label": "The places and situations where it happens most:"}, {"id": "f2", "type": "textarea", "label": "My return steps, in the order I will try them:"}, {"id": "f3", "type": "textarea", "label": "Who around me knows the signs and what they can do:"}, {"id": "f4", "type": "textarea", "label": "What I noticed this week about which steps brought me back:"}]'::jsonb, array['sexual abuse', 'grounding', 'stabilizing']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('no-go-tell-steps-poster-craft', 'No Go Tell Steps Poster Craft', 'kids'::resource_kind, 'A poster a child decorates with the three steps for an unsafe touch or secret: say no, go away, tell a trusted grown-up.', 'Use it to give a child and parent a clear, practiced script for body safety that the child made themselves.', array['Children']::text[], '40 minutes', 'Draw three big boxes with the child: a stop hand for say no, running feet for go, and a speech bubble for tell. The child decorates each and names two trusted grown-ups for the tell box. The parent practices the words with the child using safe, everyday examples such as a tickle that went on too long, and makes clear that telling is never tattling and the child is never in trouble for it. If a child discloses during this activity, follow your reporting duties and keep the child''s experience steady and unpressured.', '[{"id": "f0", "type": "textarea", "label": "My say no words and my stop hand:"}, {"id": "f1", "type": "textarea", "label": "Where I can go, and how fast my feet are:"}, {"id": "f2", "type": "textarea", "label": "My two trusted grown-ups for the tell box:"}, {"id": "f3", "type": "textarea", "label": "A pretend example my grown-up and I practiced:"}, {"id": "f4", "type": "textarea", "label": "Where we hung my poster:"}]'::jsonb, array['sexual abuse', 'children', 'safety']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('after-a-hard-session-partner-care-plan', 'After a Hard Session Partner Care Plan', 'couples'::resource_kind, 'A plan for what a partner does in the hours after the client''s hard therapy session, agreed in advance and without asking for details.', 'Use it to help a couple make the evening after a difficult session predictable and supportive.', array['Couples']::text[], '45 minutes', 'Have the client say what helps after a hard session: quiet, a meal made, a walk, a show on, no questions. The partner says what they can realistically offer and what they worry about, often whether to ask or stay silent. Agree on a signal that it was a hard day, the partner''s first move, and the rule that the client shares details only if and when they choose. The partner also names what they do for their own steadiness. Review after two sessions.', '[{"id": "f0", "type": "textarea", "label": "Client: what helps me in the hours after a hard session, and what does not:"}, {"id": "f1", "type": "textarea", "label": "Partner: what I can realistically offer, and what I worry about getting wrong:"}, {"id": "f2", "type": "textarea", "label": "Our signal that today was a hard one:"}, {"id": "f3", "type": "textarea", "label": "Partner: my first move when I see the signal, and what I will not ask:"}, {"id": "f4", "type": "textarea", "label": "Partner: what I will do for my own steadiness that evening:"}]'::jsonb, array['sexual abuse', 'couples', 'support']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('skills-borrowed-from-people-i-admire-sheet', 'Skills Borrowed From People I Admire Sheet', 'worksheet'::resource_kind, 'A sheet that lists people the client admires for how they handle hard moments and borrows one specific move from each.', 'Use it to help a client expand their coping menu with moves they have already seen work in someone they respect.', array['Adults', 'Teens', 'Groups']::text[], '25 minutes', 'Ask for three to five people, real or known from a distance, who handle stress in ways the client respects. For each, name one specific thing they do: the grandmother who goes to the garden, the coach who takes a breath before answering, the friend who says I need to think about that. Borrow it as written and try it this week. Clients who cannot think of a coping skill of their own can almost always describe one in someone else. Note which borrowed skill fit.', '[{"id": "f0", "type": "textarea", "label": "People I admire for how they handle hard moments:"}, {"id": "f1", "type": "textarea", "label": "The specific thing each one does:"}, {"id": "f2", "type": "textarea", "label": "The one I will borrow first, and when I will use it:"}, {"id": "f3", "type": "textarea", "label": "What happened when I tried it:"}, {"id": "f4", "type": "textarea", "label": "Which borrowed skill fits me, and which does not:"}]'::jsonb, array['coping skills', 'strengths', 'skills']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('helpful-versus-numbing-coping-sort-sheet', 'Helpful Versus Numbing Coping Sort Sheet', 'cbt'::resource_kind, 'A sort of everything the client does to cope into what helps them through and what only switches them off for a while.', 'Use it to help a client tell the difference between coping that carries them and coping that just mutes the day.', array['Adults', 'Teens']::text[], '25 minutes', 'List everything the client does when a day gets hard, with no judgment and nothing left off. Then sort each by two questions: how do I feel an hour later, and does this leave the problem smaller, the same or larger. Scrolling, sleeping, snapping and drinking usually sort one way; walking, calling, crying and writing another, though not always, and the client decides. Pick one item from the numbing column to swap for a helpful one at a specific moment this week.', '[{"id": "f0", "type": "textarea", "label": "Everything I do when a day gets hard:"}, {"id": "f1", "type": "textarea", "label": "For each: how I feel an hour later:"}, {"id": "f2", "type": "textarea", "label": "For each: whether it leaves the problem smaller, the same or larger:"}, {"id": "f3", "type": "textarea", "label": "What I learned from the sort:"}, {"id": "f4", "type": "textarea", "label": "One swap I will try at a specific moment this week:"}]'::jsonb, array['coping skills', 'self-monitoring', 'avoidance']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('smell-and-taste-self-soothe-menu', 'Smell and Taste Self-Soothe Menu', 'dbt'::resource_kind, 'A self-soothe menu built from smells and tastes that settle the client, with where each one lives so it is reachable when needed.', 'Use it to give a client two underused senses as fast soothing tools and make them easy to reach.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask what smells carry comfort: a soap, coffee grounds, a sweater, rain, a particular lotion. Then tastes that slow the client down: a strong mint, tea, a lemon drop, something sour. Pick six and plan where each will live: a bag, a desk drawer, the car. The menu is about soothing through the senses, never about eating as a coping tool, so keep the tastes small and the focus on attention. Have the client use one deliberately a day and rate the shift.', '[{"id": "f0", "type": "textarea", "label": "Smells that settle me, and where each comes from:"}, {"id": "f1", "type": "textarea", "label": "Small tastes that slow me down:"}, {"id": "f2", "type": "textarea", "label": "My six, and where each will live so I can reach it:"}, {"id": "f3", "type": "textarea", "label": "The one I used today, and how my distress changed, 0 to 10:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about using the senses on purpose:"}]'::jsonb, array['coping skills', 'self-soothing', 'distress tolerance']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('paper-fortune-teller-coping-craft', 'Paper Fortune Teller Coping Craft', 'kids'::resource_kind, 'A folded paper fortune teller with coping skills under the flaps, so choosing a skill becomes a game of picking a number.', 'Use it to help a child and parent pick a calm-down skill in a hard moment without a debate.', array['Children']::text[], '30 minutes', 'Fold the fortune teller together, put colors on the outside, numbers on the middle flaps, and eight skills under the inside flaps: cocoa breaths, squeeze and release, count the blues, get a drink of water, hug a pillow, draw it, tell a grown-up, jump ten times. The parent plays it at calm times first, then offers it in a hard moment: pick a color, pick a number, do the skill. The child can redo the inside when a skill stops working.', '[{"id": "f0", "type": "textarea", "label": "The colors and numbers on my fortune teller:"}, {"id": "f1", "type": "textarea", "label": "The eight skills I put under the flaps:"}, {"id": "f2", "type": "textarea", "label": "A calm-time practice we did:"}, {"id": "f3", "type": "textarea", "label": "A hard moment when we used it, and the skill that came up:"}, {"id": "f4", "type": "textarea", "label": "A skill I want to swap in:"}]'::jsonb, array['coping skills', 'children', 'craft']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('snowball-fight-coping-ideas-game', 'Snowball Fight Coping Ideas Game', 'game'::resource_kind, 'A game where players write a coping idea on paper, crumple it, have a snowball fight, then read aloud whichever one they catch.', 'Use it to get a group laughing and trading coping ideas without anyone having to own theirs out loud.', array['Groups', 'Children', 'Teens']::text[], '20 minutes', 'Each player writes one thing that helps them when they are upset, crumples it, and the group has a thirty-second indoor snowball fight. Rules: soft throws only, below the shoulders, stop on the signal. Each player picks up one snowball and reads it aloud, and the group guesses whether it would work for them. Play two rounds, the second with a prompt such as something that helps at night. Debrief on ideas worth stealing and what it was like to hear your idea read by someone else.', '[{"id": "f0", "type": "textarea", "label": "The idea I wrote on my snowball:"}, {"id": "f1", "type": "textarea", "label": "The idea I caught and read aloud:"}, {"id": "f2", "type": "textarea", "label": "An idea worth stealing from the group:"}, {"id": "f3", "type": "textarea", "label": "What it was like to hear my idea read by someone else:"}, {"id": "f4", "type": "textarea", "label": "An idea I will try this week:"}]'::jsonb, array['coping skills', 'game', 'group']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('blood-and-needle-fear-tensing-practice-notes', 'Blood and Needle Fear Tensing Practice Notes', 'worksheet'::resource_kind, 'Practice notes for tensing the large muscles before and during a blood draw or injection, to counter the faint feeling.', 'Use it to give a client with a needle or blood fear a physical practice to rehearse before an appointment.', array['Adults', 'Teens']::text[], 'Fifteen minutes daily for one week, then at the appointment', 'Teach the tensing in session: squeeze the arms, legs and torso for ten to fifteen seconds until the face feels warm, release for twenty to thirty seconds, repeat five times. Have the client check with their medical provider that it is suitable for them, and that they tell the person drawing blood they will be tensing. Practice daily, then while looking at pictures of needles, then at the appointment. Note the warm-face sign each time so they know it is working.', '[{"id": "f0", "type": "textarea", "label": "Where and when I practiced the tensing today, and how many rounds:"}, {"id": "f1", "type": "textarea", "label": "Whether I felt the warm-face sign, and how long it took:"}, {"id": "f2", "type": "textarea", "label": "What I noticed practicing while looking at pictures:"}, {"id": "f3", "type": "textarea", "label": "My plan for telling the person drawing blood that I will be tensing:"}, {"id": "f4", "type": "textarea", "label": "How the appointment went, and what I would do the same next time:"}]'::jsonb, array['phobias', 'body awareness', 'planning']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('balcony-rail-prediction-test-sheet', 'Balcony Rail Prediction Test Sheet', 'cbt'::resource_kind, 'A prediction test for a fear of heights, run on a low balcony or landing, comparing the predicted and actual outcome at each step.', 'Use it to help a client with a fear of heights test one specific prediction on a safe, railed spot.', array['Adults', 'Teens']::text[], 'One week', 'Pick a railed spot one or two floors up that the client has been avoiding. Write the predictions: I will be pulled over, my legs will give out, I will not be able to move back. Rate each. The steps: stand at the door, walk to the rail, hold the rail, look down for ten seconds, stay two minutes. Record what happened at each step against the prediction. Many clients discover their legs shook and nothing else happened, and that the shaking eased while they stayed.', '[{"id": "f0", "type": "textarea", "label": "The spot I will use, and the steps from the door to the rail:"}, {"id": "f1", "type": "textarea", "label": "My predictions, rated for how sure I am, 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "What happened at each step, compared with the prediction:"}, {"id": "f3", "type": "textarea", "label": "What my body did, and how it changed while I stayed:"}, {"id": "f4", "type": "textarea", "label": "The next spot I would try, and when:"}]'::jsonb, array['phobias', 'predictions', 'exposure']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('elevator-ride-willingness-script-page', 'Elevator Ride Willingness Script Page', 'act'::resource_kind, 'A page that scripts one elevator ride: the values it serves, the thoughts expected on each floor, and the willing stance.', 'Use it to help a client who takes the stairs out of fear ride one elevator with their values along.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what the elevator connects the client to: a job on a high floor, visiting someone in a hospital, not arriving sweaty and late. Script the ride floor by floor: what the mind will say, what the body will do, and the stance the client takes toward both, such as here is my mind telling me the doors will stick. Rate willingness, not fear, before the ride. Start with two floors if needed. Debrief on whether they rode with the fear or against it.', '[{"id": "f0", "type": "textarea", "label": "What riding the elevator would connect me to:"}, {"id": "f1", "type": "textarea", "label": "Floor by floor: what my mind will probably say:"}, {"id": "f2", "type": "textarea", "label": "What my body will probably do, and what I will let it do:"}, {"id": "f3", "type": "textarea", "label": "My willing stance toward both, in a sentence I can say silently:"}, {"id": "f4", "type": "textarea", "label": "Afterward: what happened, and whether I rode with the fear or against it:"}]'::jsonb, array['phobias', 'willingness', 'values']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-avoiding-the-feared-thing-grid', 'Pros and Cons of Avoiding the Feared Thing Grid', 'dbt'::resource_kind, 'A four-box grid weighing what avoiding a feared thing gives and costs against what approaching it would give and cost.', 'Use it to help a client with a specific fear decide, with eyes open, whether to start approaching it.', array['Adults', 'Teens']::text[], '25 minutes', 'Fill all four boxes honestly: pros of avoiding, cons of avoiding, pros of approaching, cons of approaching. Give the pros of avoiding their due, since avoidance works in the short run and the client knows it. Then ask which boxes describe the next week and which describe the next five years. The grid is a decision tool, not a push; some clients will decide the fear is not worth working on now, and that is a legitimate answer. Keep it for the day they change their mind.', '[{"id": "f0", "type": "textarea", "label": "What avoiding this gives me:"}, {"id": "f1", "type": "textarea", "label": "What avoiding this costs me, this week and over years:"}, {"id": "f2", "type": "textarea", "label": "What approaching it would give me:"}, {"id": "f3", "type": "textarea", "label": "What approaching it would cost me:"}, {"id": "f4", "type": "textarea", "label": "My decision for now, and what would change it:"}]'::jsonb, array['phobias', 'avoidance', 'decisions']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('dentist-visit-brave-picture-plan', 'Dentist Visit Brave Picture Plan', 'kids'::resource_kind, 'A picture plan a child draws of each step of a dentist visit, with a brave move for the steps they dread.', 'Use it to help a child and parent walk through the dentist before the appointment so nothing is a surprise.', array['Children']::text[], '40 minutes', 'Draw the steps as boxes: the waiting room, the big chair going back, the light, the counting of teeth, the toothbrush that buzzes, the sticker at the end. The child colors each one, marks the steps they dread with a small cloud, and chooses a brave move for each cloud: a squeeze toy, counting the ceiling tiles, a hand signal that means pause. The parent brings the plan to the appointment and shows the dentist the hand signal. Celebrate the steps done, not the absence of fear.', '[{"id": "f0", "type": "textarea", "label": "The steps of my dentist visit, in pictures:"}, {"id": "f1", "type": "textarea", "label": "The steps I marked with a cloud:"}, {"id": "f2", "type": "textarea", "label": "My brave move for each cloud:"}, {"id": "f3", "type": "textarea", "label": "My hand signal that means pause, and who knows it:"}, {"id": "f4", "type": "textarea", "label": "After the visit: the steps I did, and my sticker:"}]'::jsonb, array['phobias', 'children', 'planning']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('clothes-that-feel-good-inventory', 'Clothes That Feel Good Inventory', 'worksheet'::resource_kind, 'An inventory of the clothes a client owns sorted by how they feel to wear, not how they look, with a plan for the ones that punish.', 'Use it to help a client make getting dressed a matter of comfort and self-respect rather than a daily judgment.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask the client to go through their closet and sort by feel: pieces they feel at ease in, pieces they tolerate, and pieces that make them feel bad every time. Nothing on the sheet is about size, fit numbers or how the body looks. The punishing pieces get a decision: donate, store out of sight, or keep for a reason the client names. Plan a week of dressing only from the first pile and notice what it does to the morning.', '[{"id": "f0", "type": "textarea", "label": "Clothes I feel at ease in:"}, {"id": "f1", "type": "textarea", "label": "Clothes I tolerate:"}, {"id": "f2", "type": "textarea", "label": "Clothes that make me feel bad every time, and why I have kept them:"}, {"id": "f3", "type": "textarea", "label": "My decision for each punishing piece: donate, store, or keep for a named reason:"}, {"id": "f4", "type": "textarea", "label": "What a week of dressing from the first pile did to my mornings:"}]'::jsonb, array['body image', 'self-care', 'self-compassion']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('fitting-room-thought-record', 'Fitting Room Thought Record', 'cbt'::resource_kind, 'A thought record for the fitting room: the mirror, the lights, the thought, and a fairer reply written before the next trip.', 'Use it to help a client who leaves stores feeling worthless catch the fitting room thoughts and answer them.', array['Adults', 'Teens']::text[], '25 minutes', 'Recall the last fitting room: what the client saw, the first thought, the feeling and its strength, what they did next. Then write a fairer reply that does not praise or criticize the body, such as the lighting is brutal in here, or this is about the garment, not me. Keep the sheet away from any judgment of the body itself; the target is the verdict. Plan the next shopping trip with the reply on a phone note and a time limit for the room.', '[{"id": "f0", "type": "textarea", "label": "What I saw and the first thought I had in the fitting room:"}, {"id": "f1", "type": "textarea", "label": "What I felt, and how strongly, 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "What I did next:"}, {"id": "f3", "type": "textarea", "label": "A fairer reply that is about the room, the lights or the garment, not about my body:"}, {"id": "f4", "type": "textarea", "label": "My plan for the next trip: the reply, the time limit, and who I might go with:"}]'::jsonb, array['body image', 'thought record', 'self-talk']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('mirror-minutes-to-values-minutes-swap-page', 'Mirror Minutes to Values Minutes Swap Page', 'act'::resource_kind, 'A page that counts the minutes spent checking in mirrors and reflections and plans what those minutes could go to instead.', 'Use it to help a client see what mirror time costs and redirect some of it toward what they care about.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to estimate the minutes a day spent checking mirrors, windows and phone cameras, without judgment. Multiply out a month. Then ask what they would do with those hours if they appeared, tied to values: a class, a friend, a walk, a book. Plan one swap: a specific mirror moment they will skip this week and the values minute that replaces it. The page never asks what they see in the mirror; it asks what the looking costs.', '[{"id": "f0", "type": "textarea", "label": "Roughly how many minutes a day I spend checking mirrors, windows and cameras:"}, {"id": "f1", "type": "textarea", "label": "What that comes to in a month:"}, {"id": "f2", "type": "textarea", "label": "What I would do with that time if it appeared, tied to what I care about:"}, {"id": "f3", "type": "textarea", "label": "One mirror moment I will skip this week, and what I will do with the minute:"}, {"id": "f4", "type": "textarea", "label": "What I noticed when I made the swap:"}]'::jsonb, array['body image', 'values', 'committed action']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('fast-reply-to-body-comments-card', 'FAST Reply to Body Comments Card', 'dbt'::resource_kind, 'A FAST card for answering comments about the client''s body from family, friends or strangers while keeping self-respect.', 'Use it to give a client a rehearsed, self-respecting reply for the comments that usually leave them silent.', array['Adults', 'Teens']::text[], '25 minutes', 'List the comments the client gets: you look healthy, have you been working out, you look tired. For each, build a reply that is fair, has no over-apology, sticks to the client''s values and stays truthful, such as I would rather not talk about my body, how have you been. Rehearse aloud, including the follow-up when the commenter pushes. The card does not debate the comment''s accuracy; it closes the topic. Log each use and how the client felt afterward.', '[{"id": "f0", "type": "textarea", "label": "The comments about my body I hear most, and from whom:"}, {"id": "f1", "type": "textarea", "label": "My FAST reply for each: fair, no over-apologizing, true to my values, truthful:"}, {"id": "f2", "type": "textarea", "label": "What I will say if they push:"}, {"id": "f3", "type": "textarea", "label": "A time I used a reply this week, and what happened:"}, {"id": "f4", "type": "textarea", "label": "How I felt about myself afterward, compared with when I stay silent:"}]'::jsonb, array['body image', 'interpersonal effectiveness', 'assertiveness']::text[], '2026-11-12T15:00:00+00:00'::timestamptz),
  ('redirect-the-looks-talk-improv-game', 'Redirect the Looks Talk Improv Game', 'game'::resource_kind, 'An improv game where one player opens with a comment about appearance and the other must steer the scene somewhere else in two lines.', 'Use it to let a group practice turning appearance talk toward anything else, fast and with humor.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Pairs take the stage. Player one opens with an appearance comment from a card, such as you look different lately or you look tired. Player two has two lines to move the scene somewhere else entirely: a question, a change of subject, a plain I do not talk about bodies, then a new topic. The group votes on whether the redirect landed. Rotate roles. Debrief on which redirects felt natural, which felt rude, and which the players would actually use at a family table.', '[{"id": "f0", "type": "textarea", "label": "The opening comment I had to redirect:"}, {"id": "f1", "type": "textarea", "label": "My two lines, and whether the group said it landed:"}, {"id": "f2", "type": "textarea", "label": "A redirect someone else did that I want to borrow:"}, {"id": "f3", "type": "textarea", "label": "The redirect that felt rude, and how I would soften it:"}, {"id": "f4", "type": "textarea", "label": "The one I will use at the next family gathering:"}]'::jsonb, array['body image', 'game', 'assertiveness']::text[], '2026-11-12T15:00:00+00:00'::timestamptz)
